INSERT INTO `competencies` VALUES (1,'Tipe Data','Tipe Data','tipe-data','Membuat kode program dengan tipe data, dan operator.','[\"Tipe Data\", \"Operator\"]','2025-04-15 13:51:30','2025-04-15 13:51:30'),(2,'Struktrur Kontrol','Struktrur Kontrol','struktur-kontrol','Membuat kode program struktur kontrol.','[\"Percabangan\", \"Perulangan\"]','2025-04-15 13:51:30','2025-04-15 13:51:30'),(3,'Struktur Data','Struktur Data','struktur-data','Membuat kode program struktur data.','[\"Array\", \"List\"]','2025-04-15 13:51:30','2025-04-15 13:51:30'),(4,'Tes Psikomotorik','Tes Psikomotorik C++','psikomotorik','Tes ini bertujuan untuk mengukur pemahaman peserta didik dalam menerapkan konsep dasar pemrograman C++ melalui pengelolaan data siswa dalam suatu kelas. Peserta diminta membuat program yang menyimpan data nama, nilai, dan kehadiran siswa, menghitung total dan rata-rata nilai, menampilkan siswa dengan nilai tertinggi dan kehadiran terbaik, serta mengidentifikasi siswa yang tidak lulus dan siswa dengan kehadiran kurang dari 80%. Post test ini menilai kemampuan dalam penggunaan array, struktur kontrol (perulangan dan percabangan), serta pemilihan tipe data yang tepat dalam konteks pemrograman dasar.','[\"Tipe Data\", \"Operator\", \"Operasi Aritmatika\", \"Operasi Logika\", \"Percabangan\", \"Perulangan\", \"Array\", \"List\"]','2025-04-15 13:51:30','2025-04-15 13:51:30');
/*!40000 ALTER TABLE `competencies` ENABLE KEYS */;
UNLOCK TABLES;

