INSERT INTO `mc_questions` VALUES (1,1,'<p>Perhatikan kode berikut !</p>\r\n\r\n<p><img alt=\"\" src=\"https://drive.google.com/open?id=144BV4dqjS9WdDfkWwawt6-Bg9x54FPBn&amp;usp=drive_copy\" /><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXc3uOGkXlSHtHF2f_4OOX_TeTffyQ48br7qlIZs5NsqoFf9aZJWUGEPPsydqnKJ4uAkdVIykSG7JBY926ilGChYRgOvEt71HReCNOOXOgXlQYH7a4ofCwsSF_-HcUWRDlfMaHqiifxzkYCG__lnrGc?key=zFzzF2I3Av9NAGFzNS-ZFQ\" style=\"height:160px; width:454px\" /></p>','<p>Potongan kode mana yang seharusnya diterapkan untuk menampilkan hari pertama sesuai dengan logika program?</p>','<ul>\r\n	<li><strong>Jawaban A benar,&nbsp;</strong><code>hari[0]</code> menunjuk ke elemen pertama array, yaitu <strong>&quot;Senin&quot;</strong>.&nbsp;<code>cout</code> akan menampilkan &quot;Senin&quot; ke layar.</li>\r\n	<li><strong>Jawaban B&nbsp;salah,&nbsp;</strong><strong>&nbsp;</strong>Array <code>hari[3]</code> hanya valid untuk indeks <code>0</code>, <code>1</code>, dan <code>2</code>.&nbsp;<code>hari[3]</code> adalah <strong>di luar batas</strong>, bisa menyebabkan <strong>error runtime</strong> atau hasil tak terduga.</li>\r\n	<li><strong>Jawaban C salah,</strong> karena <strong>tidak menampilkan isi array</strong>, melainkan <strong>alamat pointer</strong>.</li>\r\n	<li><strong>Jawaban D salah,&nbsp;</strong><code>hari[1]</code> menunjuk ke elemen kedua: <code>&quot;Selasa&quot;.&nbsp;</code><strong>Bukan hari pertama</strong></li>\r\n	<li><strong>Jawaban E&nbsp;salah,&nbsp;</strong>Menampilkan teks <code>&quot;hari[1]&quot;</code> apa adanya, <strong>bukan nilai array</strong>.&nbsp;Output literal: <strong><code>hari[1]</code></strong>, bukan isi array.</li>\r\n</ul>','easy',1,NULL,'2025-05-01 07:17:24','2025-05-24 20:18:12'),(2,1,'<p>Perhatikan kode berikut ini !</p>\r\n\r\n<p><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXca5wM9J1wlLTkigoTwgz2dt-NGpjtzswHWDip7gT2rNAcNqkVvE2g7Ujtnf-5zB6kUAWW7nltAfRz2FSdJv2pOH5YCFAETm93uNlh9lV5P5kqNXZMM_ySIO6YRicgUms6qubkHlwX_3rp8OTJiYg?key=zFzzF2I3Av9NAGFzNS-ZFQ\" style=\"height:240px; width:453px\" /></p>','<p>Potongan kode mana yang perlu anda terapkan untuk menghitung total penjualan pada minggu ke-2 (baris ke-11) dan ditempatkan pada bagian komentar?</p>','<ul>\r\n	<li><strong>Jawaban A salah,</strong><strong> </strong>Karena&nbsp;menjumlahkan elemen <strong>kolom ke-1</strong> (indeks <code>1</code>) dari <strong>semua minggu</strong>. Mengakses kolom tetap, bukan baris tetap. Soal minta <strong>total minggu ke-2</strong>, bukan total kolom ke-2.</li>\r\n	<li><strong>Jawaban B&nbsp;salah,&nbsp;</strong>Mengambil baris ke-3 (<code>penjualan[2]</code>) &rarr; padahal yang diminta <strong>minggu ke-2&nbsp;</strong>&rarr; Total: <code>95 + 105 + 115 + 125 = 440</code> &rarr; <strong>Salah baris.</strong></li>\r\n	<li><strong>Jawaban C&nbsp;salah,&nbsp;</strong>Karena&nbsp;menjumlahkan <strong>kolom ke-2 dari semua minggu</strong>, bukan <strong>baris minggu ke-2</strong>.</li>\r\n	<li><strong>Jawaban D&nbsp;benar,&nbsp;&nbsp;</strong>Baris <code>penjualan[1][i]</code> menunjuk <strong>minggu ke-2.&nbsp;</strong>Perulangan <code>i &lt; 4</code> menjangkau semua kolom (hari ke-1 s/d ke-4)</li>\r\n	<li><strong>Jawaban E&nbsp;salah,&nbsp;</strong>Baris ke-0 &rarr; berarti <strong>minggu ke-1</strong>, bukan ke-2.&nbsp;&rarr; Hasil: <code>100 + 120 + 130 + 150 = 500</code> &rarr; <strong>Salah baris.</strong></li>\r\n</ul>','medium',1,NULL,'2025-05-01 07:17:24','2025-05-24 17:43:34'),(4,1,'<p>Perhatikan kode berikut !</p>\r\n\r\n<p><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXfDPDd3VKvdzGQfxaChPyZQr1XbzQ6ChDIoWwdyQOkr06UqgZvJzS7ts_9StAXPM7bHahGXs1y0cLh5dk9Vikq8p6JbzeUX2NA3gMv015ONpBkUjO-aYgygEEaTjejA-p0CfIpVKqglQWebwtpiVxg?key=zFzzF2I3Av9NAGFzNS-ZFQ\" style=\"height:237px; width:454px\" /></p>','<p>Potongan kode manakah yang dapat anda terapkan untuk menghitung dan menampilkan rata-rata nilai Budi dengan benar?</p>','<ul>\r\n	<li><strong>Jawaban A&nbsp;salah, </strong>Karena&nbsp;menghitung nilai <strong>Citra</strong> (<code>baris ke-2</code>) bukan Budi.&nbsp;<strong>Salah akses baris.</strong></li>\r\n	<li><strong>Jawaban B&nbsp;salah, </strong>Karena&nbsp;menjumlahkan nilai <strong>Ali</strong> (<code>baris ke-0</code>).&nbsp;<strong>Salah baris.</strong></li>\r\n	<li><strong>Jawaban C&nbsp;salah,&nbsp;</strong>Karena&nbsp;menjumlahkan <strong>kolom ke-1</strong> dari semua siswa: <code>85 + 70 + 95</code></li>\r\n	<li><strong>Jawaban D&nbsp;salah,&nbsp;</strong>Karena&nbsp;<strong>kode tidak melakukan pembagian</strong> untuk menghitung rata-rata.</li>\r\n	<li><strong>Jawaban E benar,&nbsp;</strong>Menggunakan loop &rarr; cocok untuk data besar atau dinamis.&nbsp;<code>total</code> diisi dari baris ke-1 (<code>nilai[1][i]</code>)</li>\r\n</ul>','medium',1,NULL,'2025-05-04 07:12:59','2025-05-24 21:17:38'),(7,1,'<p>Perhatikan kode berikut ini !</p>\r\n\r\n<p><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXe4TwaVEefo0OkUAAljHeMgLx3eElfocpm7tDc0wJ8TZoRUBPSXBIWdQQB0xPxt-n7VN8FIIbXWi1_uHci6tGR0QkdmnBPVvg20YFZbJAVckr0MAVhHVVaI6KO3UNGZiM_b1FwFi3D5SKIz1XTtCro?key=zFzzF2I3Av9NAGFzNS-ZFQ\" style=\"height:253px; width:454px\" /></p>','<p>Bagaimana cara anda menerapkan potongan kode yang tepat untuk menemukan dan menampilkan siswa dengan rata-rata nilai tertinggi dari data yang tersedia?</p>','<ul>\r\n	<li><strong>Jawaban A benar,&nbsp;</strong>Loop baris per siswa (<code>i</code>). Menghitung rata-rata dan membandingkan seluruh siswa</li>\r\n	<li><strong>Jawaban B&nbsp;salah,&nbsp;</strong>Menyimpan nilai <code>total</code>, <strong>bukan rata-rata.&nbsp;</strong>Jika semua siswa punya jumlah elemen yang sama, <strong>tidak berpengaruh.&nbsp;</strong>Tapi <strong>tidak menghitung rata-rata</strong>, jadi secara konteks soal <strong>kurang tepat</strong></li>\r\n	<li><strong>Jawaban C&nbsp;salah,&nbsp;</strong>Hanya membandingkan <strong>nilai pertama</strong> dari masing-masing siswa.&nbsp;<strong>Bukan rata-rata</strong>, hanya <code>nilai[i][0]</code></li>\r\n	<li><strong>Jawaban D&nbsp;salah, K</strong>ode langsung ke <code>index = 2</code> (Citra). Tidak menghitung atau membandingkan</li>\r\n	<li><strong>Jawaban E&nbsp;salah,&nbsp;</strong>Bukan mencari <strong>rata-rata tertinggi.&nbsp;</strong>Bisa mencetak <strong>lebih dari satu siswa</strong>, tidak sesuai perintah soal</li>\r\n</ul>','hard',1,NULL,'2025-05-04 07:17:06','2025-05-24 21:47:13'),(8,1,'<p>Perhatikan kode berikut ini !</p>\r\n\r\n<p><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXdip4ySj1rmYkT6qMx95y5SoZuRAlXkccYdd0ZcHWIB3Uwy1Pidce10FjOFBa2ezMxGfDKNuvDTE_cifW5WADBBYFipe4fPSk9pwbI-ZuDRWrBEo5EuJsynh1nqoPt0PuTToPPzp3n2B2TzgIgX7JM?key=zFzzF2I3Av9NAGFzNS-ZFQ\" style=\"height:361px; width:454px\" /></p>','<p>Setelah menganalisis logika dalam fungsi process, potongan kode manakah yang paling sesuai untuk menggandakan setiap elemen array arr [ ] tanpa mengubah struktur utama program?</p>','<ul>\r\n	<li>\r\n	<p><strong>Jawaban A salah,&nbsp;</strong>arr[i] = arr[i] + 2;.&nbsp;Menambahkan 2 ke nilai elemen, bukan menggandakan.&nbsp;Misal arr[i] = 4, maka hasilnya: 6, bukan 8.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Jawaban B salah, K</strong>arena tidak mempertahankan nilai awal dan bukan penggandaan.<strong>&nbsp;</strong>Mengganti semua elemen array menjadi <code>2</code>.&nbsp;</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Jawaban C benar,&nbsp;</strong>Nilai lama pada <code>arr[i]</code> dikalikan 2, lalu ditulis kembali ke <code>arr[i]</code>.&nbsp;Inilah bentuk <strong>penggandaan nilai</strong> pada elemen array.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Jawaban D salah</strong>, karena <strong>mengisi array dengan pola baru</strong> berdasarkan indeks (<code>i * 2</code>) dan <strong>bukan menggandakan</strong> nilai asli array.</p>\r\n	</li>\r\n	<li>\r\n	<p><strong>Jawaban E salah,&nbsp;</strong><code>*(arr + i)</code> adalah cara lain menulis <code>arr[i]</code>.&nbsp;Maka ini setara dengan,&nbsp;<code>arr[i] = arr[i] * arr[i];. </code><code>A</code><strong>rtinya:</strong> elemen array dikuadratkan, bukan digandakan</p>\r\n	</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>','easy',1,NULL,'2025-05-04 07:18:58','2025-05-24 16:40:04'),(9,1,'<p>Perhatikan kode berikut ini !</p>\r\n\r\n<p><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXdkCPtbIv1jcYJM1jprqhWPgS0cycvfUWqb28vR-xc6MzaZNf5rxO5Se1U1DOVkmodxbBjgdiC6h2LcIiHUOK68Hz9k87TDotBzdA_DN0NkATjlzJMK76SslvuepTZFUaQM-pCl0bxhRrDUHl-Gmg?key=zFzzF2I3Av9NAGFzNS-ZFQ\" style=\"height:458px; width:549px\" /></p>','<p>Analisislah karakteristik nilai yang mungkin muncul pada program, kemudian tentukan tipe data yang paling sesuai untuk mengisi placeholder ___ pada baris 8, 11, dan 13, dengan mempertimbangkan kebutuhan representasi pecahan harga, akurasi hasil perkalian untuk diskon, serta perhitungan total harga yang meminimalkan risiko pembulatan...</p>','<ul>\r\n	<li><strong>Jawaban A salah,&nbsp;</strong>Karena tidak bisa menyimpan nilai pecahan &rarr; <strong>semua perhitungan pecahan dibulatkan</strong> &rarr; hasil tidak akurat.</li>\r\n	<li><strong>Jawaban B&nbsp;salah,&nbsp;</strong><code>totalHarga</code> bertipe <code>int</code>, padahal hasil pengurangan bisa pecahan &rarr; <strong>terjadi pembulatan</strong>.</li>\r\n	<li><strong>Jawaban C&nbsp;salah, j</strong><code>umlahDiskon</code> harusnya pecahan, tapi diset <code>int</code> &rarr; <strong>diskon dibulatkan ke bawah</strong>.</li>\r\n	<li><strong>Jawaban D&nbsp;benar,&nbsp;</strong>Menggunakan <code>double</code> untuk semua variabel pecahan &rarr; <strong>akurat dan presisi tinggi.</strong></li>\r\n	<li><strong>Jawaban E&nbsp;salah,&nbsp;</strong><code>totalHarga</code> bertipe <code>int</code>, padahal hasil akhirnya pecahan &rarr; <strong>hasil jadi tidak akurat</strong>.</li>\r\n</ul>\r\n\r\n<p>Gunakan <strong><code>double</code> untuk semua</strong> variabel pecahan seperti harga, diskon, dan total &rarr; karena lebih presisi dibanding <code>float</code>, dan tidak membulatkan seperti <code>int</code>.</p>','medium',1,NULL,'2025-05-04 07:20:35','2025-05-24 17:19:49'),(10,1,'<p>Perhatikan kode berikut ini !</p>\r\n\r\n<p><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXd6ys5xysgJ2NlUTWjDgutyqpwYAcLbBTCEnwPm51KPzh5vxkiRId9aVeqj_jbZr3sr_EY50OmjQatMsKJyCmAMbWF8kkt5vqt4qdcVNABBmX4eGTkGLE2_5UlVhfcrMZPsK4Iyb3PYLAyJJ2eTSK0?key=zFzzF2I3Av9NAGFzNS-ZFQ\" style=\"height:247px; width:491px\" /></p>','<p>Analisislah, manakah pernyataan kode program yang paling tepat berdasarkan hasil analisis terhadap kesalahan penggunaan tipe data dan logika dalam program tersebut?</p>','<ul>\r\n	<li><strong>Jawaban A benar,&nbsp;</strong>pakai <strong><code>vector&lt;float&gt;</code></strong> karena nilai bisa berupa desimal (misalnya: 70.5, 85.25).&nbsp;Kita pakai <strong><code>double total = 0.0;</code></strong> agar hasil penjumlahan presisi, tidak dipotong.&nbsp;Ini kombinasi <strong>tipe data yang benar</strong> untuk menghitung <strong>rata-rata</strong> nilai siswa.</li>\r\n	<li>Jawaban B salah,&nbsp;Walaupun ini bisa <strong>berfungsi dengan benar</strong>, ini <strong>bukan yang paling efisien</strong>. Juga tidak ada titik koma ;</li>\r\n	<li>Jawaban C&nbsp;salah,&nbsp;Penjumlahan <code>float</code> (nilai desimal) dengan <code>int</code> membuat hasil rata-rata <strong>tidak akurat</strong>.&nbsp;Hasil akan <strong>dipotong</strong> ke bilangan bulat, jadi jawaban akhirnya bisa <strong>salah besar</strong>.</li>\r\n	<li>Jawaban D&nbsp;salah,&nbsp;pakai <code>int</code> untuk total akan membuat <strong>hasil rata-rata salah</strong>.&nbsp;Selain itu, pakai <code>double</code> untuk <code>nilai[]</code> terlalu berat (boros memori) jika tidak butuh banyak presisi.</li>\r\n	<li>Jawaban E&nbsp;salah,&nbsp;Nilai awal <code>0</code> bertipe <strong>int</strong>, jadi penjumlahan dilakukan dengan tipe <code>int</code> juga.&nbsp;Akibatnya, <strong>angka desimal dipotong</strong>, dan hasil rata-rata <strong>jadi tidak presisi</strong>.&nbsp;Harusnya pakai <code>0.0</code> agar penjumlahan dilakukan dalam <strong>double</strong>.</li>\r\n</ul>','medium',1,NULL,'2025-05-04 07:21:49','2025-05-25 07:19:30'),(11,1,'<p>Perhatikan kode berikut ini !</p>\r\n\r\n<p><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXeSSuNnMs4oRsU58N77RFeBLzALE_H0p82XZ8SRrz_zmNpQpATqz8JzSuBIhn0Hi1tkD04eVhHEGfWu79aCoAMvogQu6U6-XS2eL9VFAcElbhFAvlp8-oEa75_e0RqHhTCbBIP1YMFe-dTdM6wPMzc?key=zFzzF2I3Av9NAGFzNS-ZFQ\" style=\"height:288px; width:416px\" /></p>','<p>Setelah menganalisis kesalahan pada baris 3 &ndash; 6 terkait presisi pembagian, risiko overflow, dan potensi memory leak, potongan kode manakah yang paling tepat digunakan sebagai pengganti untuk memperbaiki seluruh permasalahan tersebut secara efektif?</p>','<ul>\r\n	<li><strong>Jawaban A&nbsp;benar,&nbsp;</strong><code>long long</code> menghindari <strong>integer overflow.&nbsp;</strong><code>static_cast&lt;double&gt;</code> memastikan <strong>pembagian pecahan.&nbsp;</strong><code>delete[] data</code> menyelesaikan <strong>memory leak.</strong></li>\r\n	<li><strong>Jawaban B salah,&nbsp;</strong><code>float</code> punya presisi lebih rendah dari <code>double.&nbsp;</code>Pada data besar, <code>float</code> bisa kehilangan akurasi penjumlahan.&nbsp;Tetap <strong>tidak ada <code>delete[]</code></strong> &rarr; memory leak</li>\r\n	<li><strong>Jawaban C&nbsp;salah,&nbsp;</strong><code>sum / 10000</code> dilakukan sebagai pembagian integer &rarr; presisi hilang.&nbsp;<code>float avg</code> menerima hasil pembulatan.</li>\r\n	<li><strong>Jawaban D&nbsp;salah, l</strong>oop<strong> hanya menjumlah <code>i</code></strong>, bukan <code>data[i]</code> &rarr; logika perhitungan SALAH.&nbsp;<code>delete data;</code> &rarr; seharusnya <code>delete[] data;</code> (sintaks salah).</li>\r\n	<li><strong>Jawaban E&nbsp;salah, h</strong>anya pembagian yang dibenahi (<code>/ 10000.0</code>), <strong>masalah sum dan memory leak tidak diselesaikan.</strong></li>\r\n</ul>','hard',1,NULL,'2025-05-04 07:23:20','2025-05-25 03:02:20'),(12,1,'<p>Perhatikan kode program berikut ini !</p>\r\n\r\n<p><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXdcdeFT3P7Qy1NcS5lQRgdzPCWBZWy_rYw0Zkcjvy0jxCFB25yuDehK4znEmCA1O5EsjBIbi8JF8H8db9sG0O2gqvp5kMTgPQIhCpIxXvvzMVXv5CbfLz_vLii8TwcFSGDCPe9Cx2NVQ0A63QIOxzI?key=zFzzF2I3Av9NAGFzNS-ZFQ\" style=\"height:352px; width:416px\" /></p>','<p>Evaluasilah logika program tersebut, agar seluruh elemen tetap diperiksa dan semua bilangan positif terhitung...</p>','<ul>\r\n	<li>\r\n	<p><strong><code>break;</code></strong> pada <code>else</code> menyebabkan <strong>perulangan berhenti saat menemukan angka non-positif pertama</strong>.</p>\r\n	</li>\r\n	<li>\r\n	<p>Akibatnya, <strong>tidak semua elemen array diperiksa</strong>, padahal tujuannya adalah menghitung semua angka positif dalam array.</p>\r\n	</li>\r\n	<li>Data <code>{3, -2, 7, 0, 5, -1}</code> &rarr; hanya <code>3</code> dihitung karena <code>-2</code> membuat <code>break</code>.</li>\r\n</ul>\r\n\r\n<hr />\r\n<ul>\r\n	<li>Jawaban A salah,&nbsp;<code>continue</code> tidak salah, tapi tidak perlu</li>\r\n	<li>Jawaban B salah,&nbsp;<code>count--</code> salah logika, menghitung mundur</li>\r\n	<li><strong>Jawaban C benar,&nbsp;</strong>Karena pengecekan dilakukan di <code>if</code>, dan <code>count++</code> hanya terjadi untuk bilangan positif, maka <strong>else bisa dikosongkan</strong>.&nbsp;Dengan begini, <strong>semua elemen diperiksa</strong> dan hanya bilangan positif yang dihitung.</li>\r\n	<li>Jawaban D salah,&nbsp;<code>break</code> menyebabkan loop berhenti terlalu cepat</li>\r\n	<li>Jawaban E salah,&nbsp;<code>i++</code> sudah dilakukan setelah blok <code>if/else</code>, maka melakukan <code>i++</code> di sini menyebabkan <strong>loncatan ganda</strong>.&nbsp;Akibatnya, <strong>beberapa elemen akan dilewati</strong> (misal: hanya memeriksa elemen indeks 0, 2, 4, ...).</li>\r\n</ul>','easy',1,NULL,'2025-05-04 07:24:50','2025-05-25 03:07:43'),(13,1,'<p>Perhatikan kode berikut ini !</p>\r\n\r\n<p><img alt=\"C:\\Users\\Lenovo\\AppData\\Local\\Microsoft\\Windows\\INetCache\\Content.Word\\10 C5 SOAL SEDANG.PNG\" src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXeZkiDukp2qbcCJEjAkNob6jSeoJC_w5-VSTZWbB6NhZ33NUM8-84UyNVIjN7P-h1aT9Br5cH8gpaYsVqgm5psFnCe7fVeSltjvnPTatgpsl5bbI1q6Eniq3mpmWXGeISI3J5g75pfteZUtE8evsh0?key=zFzzF2I3Av9NAGFzNS-ZFQ\" style=\"height:236px; width:500.2954902080659\" /></p>','<p>Evaluasilah fungsi findMax, terdapat potensi kesalahan logika pada struktur kontrol loop, dan rekomendasikan perbaikan yang paling tepat agar fungsi mengembalikan nilai maksimum dengan benar tanpa menimbulkan error...</p>','<ul>\r\n	<li>\r\n	<p>Loop menggunakan <strong><code>i &lt;= n</code></strong>, padahal indeks valid hanya dari <code>0</code> sampai <code>n-1</code>.</p>\r\n	</li>\r\n	<li>Ini menyebabkan <code>arr[n]</code> diakses &rarr; <strong>out of bounds</strong> &rarr; <strong>undefined behavior / runtime error</strong>.</li>\r\n</ul>\r\n\r\n<hr />\r\n<ul>\r\n	<li>Jawaban A salah,&nbsp;Ekspresi <code>arr[i] &gt; maxVal</code> tidak terkelompok dengan benar.&nbsp;Operator <code>&amp;&amp;</code> dan <code>&gt;</code> membentuk <strong>logika ambigu</strong>.</li>\r\n	<li>Jawaban B salah,&nbsp;Sintaks error (<code>arr[]</code> tanpa indeks)</li>\r\n	<li><strong>Jawaban C benar,&nbsp;</strong><code>i &lt; n</code> memastikan indeks tidak melebihi batas array. Perbaikan yang tepat agar tidak terjadi <strong>out-of-bounds access</strong>.</li>\r\n	<li>Jawaban D&nbsp;salah,&nbsp;Fungsi dipanggil dengan <code>n = 4</code>, padahal <code>data</code> berisi 5 elemen.&nbsp;Maka nilai terakhir (<code>7</code>) tidak ikut diproses.</li>\r\n	<li>Jawaban E salah,&nbsp;Perulangan <strong>do-while</strong> dimulai dari <code>i = 1</code>, lalu langsung <code>i++</code>, sehingga dimulai dari <code>i = 2</code>.&nbsp;Selain itu, <code>i &lt;= n</code> kembali mengakses <code>arr[n]</code>, yang <strong>tidak valid</strong>.</li>\r\n</ul>','medium',1,NULL,'2025-05-04 07:26:21','2025-05-25 03:19:39'),(14,1,'<p>Perhatikan kode berikut ini !</p>\r\n\r\n<p><strong><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXdz7AD1CZNZ4fgKeeL9KMHlbzP2bHukfhIcLx-BpIw9rPBEiRNaKPb87B9SwhcmyHoO5Q2otWzR09A95zjFDupSry8spdt8sTiZhF16T5b3P4mGkIh_Rbmtq9aN-TPcSQpQf2vFVtuUFmTwXebkAOw?key=zFzzF2I3Av9NAGFzNS-ZFQ\" style=\"height:400px; width:555px\" /></strong></p>','<p>Evaluasilah perulangan dalam fungsi process untuk menilai kesalahan logika pada struktur for, while, dan do-while yang menyebabkan akses di luar batas atau elemen tidak terproses. Rekomendasikan potongan kode pengganti agar ketiganya dapat memproses seluruh elemen arr[0] hingga arr[n-1] dengan benar&hellip;</p>','<ul>\r\n	<li>\r\n	<p><code>for</code> memproses dari <code>0</code> ke <code>n-1</code>.</p>\r\n	</li>\r\n	<li>\r\n	<p><code>while</code> memeriksa dan menambahkan <code>j++</code> <strong>dalam</strong> kondisi aman.</p>\r\n	</li>\r\n	<li><code>do-while</code> juga memastikan kondisi <code>k &lt; n</code>.</li>\r\n</ul>\r\n\r\n<hr />\r\n<ul>\r\n	<li><strong>Jawaban A adalah BENAR.&nbsp;</strong>Semua indeks <code>0</code> hingga <code>n-1</code> diproses dengan aman. Tidak ada potensi error.</li>\r\n	<li>Jawaban B salah,&nbsp;<code>j &lt;= n</code> memungkinkan <code>arr[n]</code> diakses (padahal indeks maksimum <code>arr[n-1]</code>) &rarr; <strong>out of bounds error.&nbsp;</strong>Loop akan berhenti saat <code>k == n-1</code>, jadi <code>arr[n-1]</code> tidak masuk proses.</li>\r\n	<li>Jawaban C salah,&nbsp;<code>i &lt;= n</code> &rarr; akses indeks <code>arr[n]</code>, menyebabkan <strong>runtime error</strong>.</li>\r\n	<li>Jawaban D salah, Loop dimulai dari <code>i = 1</code>, artinya elemen pertama <strong>tidak diperiksa</strong>.&nbsp;while (k &lt; n - 1)&nbsp;(arr[n-1] tidak ikut diperiksa)&nbsp;elemen penting terlewatkan.</li>\r\n	<li>Jawaban E salah,&nbsp;Loop <code>k = 1</code> melewatkan <code>arr[0]</code>.&nbsp;<code>k &lt; n - 1</code> melewatkan <code>arr[n-1]</code>.&nbsp;Artinya: hanya&nbsp;memproses dari <code>arr[1]</code> hingga <code>arr[n-2]</code>, banyak data terlewat.</li>\r\n</ul>','medium',1,NULL,'2025-05-04 07:27:27','2025-05-25 04:16:07'),(15,1,'<p>Perhatikan kode berikut ini !</p>\r\n\r\n<p><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXfme30XBPftnvAAHHeBri-GLrzPGxR9TMYDKJksUVJ1WgKCtEGUQWVInrRycfSoFRhwQ2f2gq4RadbzM_DODyRF5YbYQYAzgvgf0Cqo5foXSCEHnx5BU45ZcsGq58GHaCYbQ7Gx4xeu_nS3LrK5Fys?key=zFzzF2I3Av9NAGFzNS-ZFQ\" style=\"height:384px; width:529px\" /></p>','<p>Evaluasilah fungsi prosesData dan nilai efektivitas logikanya terkait pengaksesan array, kontrol perulangan, dan validitas perhitungan. Rekomendasikan potongan kode pengganti yang paling tepat untuk menghindari akses di luar indeks, memastikan akumulasi bilangan genap berjalan utuh, serta mengecualikan data negatif dari proses perhitungan ...</p>','<ul>\r\n	<li><strong>Jawaban A benar,&nbsp;</strong>Data negatif di-<em>skip</em>.&nbsp;Bilangan genap saja yang dijumlahkan.&nbsp;Perhitungan <code>hitung</code> hanya untuk data yang valid.</li>\r\n	<li>Jawaban B salah,&nbsp;<code>break</code> menghentikan seluruh proses saat menemukan data negatif pertama.Akibatnya, data setelahnya tidak diproses walau valid.&nbsp;<code>i</code> dimulai dari 1, sehingga <strong>elemen pertama <code>nilai[0]</code> dilewati</strong>.</li>\r\n	<li>Jawaban C salah, Perulangan utama <code>i &lt;= jumlahData</code> menyebabkan <strong>akses indeks di luar batas array</strong> (<code>nilai[i]</code>) saat <code>i == jumlahData</code>.</li>\r\n	<li>Jawaban D salah,&nbsp;<code>break</code> menghentikan proses jika menemukan bilangan ganjil.&nbsp;Artinya hanya <code>j = 0</code> yang dijumlahkan &mdash; tidak sesuai tujuan menjumlahkan semua genap dalam rentang nilai.</li>\r\n	<li>Jawaban E salah,&nbsp;Ada titik koma <code>;</code> setelah while, sehingga perulangan tidak berjalan, dan baris <code>if (j % 2 == 0)</code> menjadi bagian dari blok terpisah, bukan dari perulangan. Ini menyebabkan loop tidak berfungsi seperti yang diinginkan.</li>\r\n</ul>','hard',1,NULL,'2025-05-04 07:28:35','2025-05-25 06:56:21'),(16,1,'<p>Perhatikan kode berikut ini !</p>\r\n\r\n<p><strong><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXfSE0PhCPlgnOxn_O47NTqP8AoMF5cJsTfBCEIlpsaMg98kCIfTUVU92h597HUxJkgey0GzGKzep6WfB4y5QkaXq0jFwegKM4_8MJwpNLTdugejnvGjiphM5Mc6De94QcKdFX2e5X7J0Ho7SEnHn4I?key=zFzzF2I3Av9NAGFzNS-ZFQ\" style=\"height:150px; width:529px\" /></strong></p>','<p>Manakah perancanganRancanglah kode yang paling tepat untuk menciptakan fungsi hitungLuas dan menyusun program utama (main) agar dapat menerima input panjang dan lebar dari pengguna, menghitung luas persegi panjang, serta menampilkan hasilnya ke layar? array yang paling tepat agar Andi dapat menyimpan nama lima siswa dalam program tersebut...</p>','<ul>\r\n	<li>Jawaban&nbsp;A&nbsp;salah,&nbsp;Kesalahan&nbsp;pada&nbsp;baris&nbsp;<code>float&nbsp;luas&nbsp;=&nbsp;panjang&nbsp;/&nbsp;lebar;</code>,&nbsp;seharusnya&nbsp;perkalian&nbsp;(<code>*</code>)&nbsp;untuk&nbsp;menghitung luas, bukan pembagian.</li>\r\n	<li>Jawaban B salah,&nbsp;Fungsi <code>hitungLuas</code> tidak mengembalikan nilai (<code>void</code>), padahal deklarasinya <code>float</code>. Selain itu, mencetak hasil langsung di dalam fungsi adalah praktik yang kurang tepat untuk fungsi hitung.</li>\r\n	<li>Jawaban C salah,&nbsp;logika hitung luas seharusnya <code>panjang * lebar</code>, tetapi di sini digunakan <code>panjang + lebar</code>, yang berarti menghitung keliling sisi pendek, bukan luas.</li>\r\n	<li><strong>Jawaban D benar,</strong>&nbsp;Fungsi menghitung luas dengan benar, dan <code>main</code> menangani input dari pengguna lalu mencetak hasil dengan baik.</li>\r\n	<li>Jawaban E salah,&nbsp;Fungsi <code>hitungLuas</code> mengubah <code>float</code> ke <code>int</code>, menyebabkan <strong>hilangnya presisi</strong> (bilangan desimal dibulatkan). Ini menjadikan perhitungan tidak akurat.</li>\r\n</ul>','easy',1,NULL,'2025-05-04 07:30:26','2025-05-25 04:27:25'),(17,1,'<p>Perhatikan kode berikut ini !</p>\r\n\r\n<p><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXdkKeDfMk9CApRFZ8kwfoiiQzSHiGzeU9DQF76pZRzgNzwMnYxiCMsFqGetsTY0jWaa5eyPf88rIIXNrEHPSzjUUuDqNpJEOEVcs8r7Xn1j5gGjf3zUNJsQdOV3hoeqtVfJ8AtsQqzX7yKBajUBdSA?key=zFzzF2I3Av9NAGFzNS-ZFQ\" style=\"height:267px; width:552px\" /></p>','<p>Bagaimana anda merancang potongan kode (pada baris 8) untuk menciptakan implementasi fungsi hitungRataTengah dengan merancang logika yang mencakup: menemukan nilai minimum dan maksimum dalam data[ ], menjumlahkan seluruh elemen kecuali nilai minimum dan maksimum, serta menghitung rata-rata berdasarkan jumlah elemen yang tersisa...</p>','<ul>\r\n	<li>Jawaban A salah,&nbsp;hanya menghitung <strong>rata-rata semua data</strong>.&nbsp;Tidak mengecualikan <strong>nilai minimum dan maksimum</strong>, sehingga <strong>tidak menjawab soal</strong>.</li>\r\n	<li><strong>Jawaban B benar,&nbsp;</strong>Loop mencari <code>minVal</code> dan <code>maxVal</code> sambil menjumlahkan <code>sum</code>.&nbsp;<code>data[0]</code> memang belum dijumlahkan, <strong>jadi perlu diproses terpisah</strong> atau pakai indeks <code>i = 0</code> dari awal <strong>lalu dijumlahkan</strong>.&nbsp;Sudah menghitung rata-rata <strong>tanpa min dan max.</strong></li>\r\n	<li>Jawaban C&nbsp;salah,&nbsp;<code>minVal</code> dan <code>maxVal</code> <strong>hanya diambil dari elemen pertama dan terakhir</strong>, bukan dihitung dari seluruh data.&nbsp;Jika nilai minimum/maksimum <strong>tidak</strong> berada di posisi itu, hasil akan <strong>salah</strong>.&nbsp;Selain itu, <code>n</code> tidak dideklarasikan di fungsi.</li>\r\n	<li>Jawaban D salah,&nbsp;sudah mengurangkan <code>minVal</code> dan <code>maxVal</code>, tetapi <strong>jumlah data</strong> (penyebut) masih <code>jumlahData</code>, seharusnya <strong><code>jumlahData - 2</code></strong>.</li>\r\n	<li>Jawaban E salah,&nbsp;Hanya menjumlahkan <strong>elemen tengah</strong> (dari indeks 2 hingga <code>n-3</code>) tanpa memperhitungkan nilai min dan max.&nbsp;Tidak ada proses mencari <code>minVal</code> dan <code>maxVal</code>.&nbsp;Pembagian <code>(jumlahData - 4)</code> tidak relevan.</li>\r\n</ul>','medium',1,NULL,'2025-05-04 07:31:28','2025-05-25 04:58:49'),(18,1,'<p>Perhatikan kode berikut ini !</p>\r\n\r\n<p><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXeJg9Fr3IgmHTEcm_TMmunQ2Fb73i3YuQrNGe-I6yfB7bH5cb-tpixMzu0jy-i1mAj6wmwKNxyFUpivab0d5lrVaDfLiffSq3Y7cadc-u4acV0W1ct25pGx12lVclg9erUbCAPKayuejtWn_D8P7Q?key=zFzzF2I3Av9NAGFzNS-ZFQ\" style=\"height:199px; width:529px\" /></p>','<p>Bagaimana anda merancang dan membangun fungsi cariRunTerpanjang serta menyusun main( ) agar program dapat: membaca input array dari pengguna, menghitung panjang subsekuens nilai yang meningkat secara berurutan, dan menampilkan output dalam format: Panjang run terpanjang:&nbsp; X&nbsp;..?</p>','<ul>\r\n	<li>Jawaban A salah,&nbsp;Loop <code>while</code> berisiko <strong>akses di luar indeks</strong> saat <code>currentRun = 0</code>, karena <code>data[currentRun - 1]</code> akan menjadi <code>data[-1]</code>.</li>\r\n	<li>Jawaban B salah,&nbsp;Tidak mengupdate <code>maxRun</code> dengan <code>currentRun</code>. Nilai <code>maxRun</code> akan tetap stagnan. Salah logika perhitungan run.</li>\r\n	<li><strong>Jawaban C benar,&nbsp;</strong>Menggunakan <code>currentRun</code> untuk mencatat panjang run saat ini.&nbsp;Saat run berakhir (<code>else</code>), <code>maxRun</code> diperbarui jika <code>currentRun</code> lebih panjang.&nbsp;Setelah <code>for</code>, masih ada <code>if</code> untuk mengantisipasi run terakhir.</li>\r\n	<li>Jawaban D salah, Menggunakan <code>data[i - 2]</code> bukan <code>data[i - 1]</code>, tidak tepat untuk run terpanjang.</li>\r\n	<li>Jawaban E salah,&nbsp;Tidak menambah <code>currentRun</code> secara benar, hanya menambah <code>i</code>, dan <code>maxRun</code> hanya diset saat penurunan. Tidak menyimpan run terpanjang yang valid.</li>\r\n</ul>','medium',1,NULL,'2025-05-04 07:32:23','2025-05-25 05:21:09'),(19,1,'<p>Perhatikan kode berikut ini !</p>\r\n\r\n<p><img src=\"https://lh7-rt.googleusercontent.com/docsz/AD_4nXe5ee09oWGvEwYWR4ZWAlMb1q3izOYtehNQisAOOk2gT09Ixv6HVRjCUCCqAdRsRKDn4BH1J0EGC11EyFwcc9Ih70efj6PNHcj6heoHhckk3F5NlZaO1FhcC4i97g4gf0vAEySv5mtwer1hoQ98Y-M?key=zFzzF2I3Av9NAGFzNS-ZFQ\" style=\"height:206px; width:453px\" /></p>','<p>Bagaimana anda merancang kode program agar dapat memproses data bilangan prima dengan efisien dan mudah dikembangkan, mulai dari pengecekan keprimaan, pengisian array baru, hingga penampilan hasil ...</p>','<ul>\r\n	<li>Jawaban A&nbsp;salah,&nbsp;semua bilangan ganjil dianggap prima.</li>\r\n	<li>Jawaban B&nbsp;salah,&nbsp;&nbsp;<code>d != data[i]</code> salah, karena d bisa bernilai 1. Ini akan melewatkan pembagi selain dirinya.&nbsp;Tidak memeriksa bilangan kurang dari 2 (misal 1 dianggap prima, padahal bukan).</li>\r\n	<li>Jawaban C&nbsp;salah,&nbsp;Anggapan <strong>semua bilangan ganjil adalah prima</strong> salah.&nbsp;Contoh 9, 15, 21 adalah ganjil tapi bukan prima.</li>\r\n	<li>Jawaban D&nbsp;salah, hanya memeriksa 4 angka (2,3,5,7), padahal bilangan prima bisa lebih besar (11, 13, 17, dst).</li>\r\n	<li><strong>Jawaban E benar,</strong>&nbsp;Logika benar, efisien (<code>d * d &lt;= data[i]</code>), hanya menyimpan bilangan prima, array dialokasikan sesuai jumlah bilangan prima.</li>\r\n</ul>','hard',1,NULL,'2025-05-04 07:33:22','2025-05-25 06:37:52');
/*!40000 ALTER TABLE `mc_questions` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `mcq_result_details`
--

DROP TABLE IF EXISTS `mcq_result_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mcq_result_details` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `mcq_result_id` bigint unsigned NOT NULL,
  `mc_question_id` bigint unsigned NOT NULL,
  `option_id` bigint unsigned DEFAULT NULL,
  `correct` tinyint(1) NOT NULL,
  `score` int NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `mcq_result_details_mcq_result_id_foreign` (`mcq_result_id`),
  KEY `mcq_result_details_mc_question_id_foreign` (`mc_question_id`),
  KEY `mcq_result_details_option_id_foreign` (`option_id`),
