INSERT INTO `pgw_problems` VALUES (5,19,'Bagaimana cara mencatat dan merekap kehadiran siswa secara akurat dan efisien agar tidak terjadi kehilangan data dan kesalahan penulisan?','Tersedia sistem pencatatan digital, Proses rekap otomatis per minggu, dan Tidak terjadi kehilangan data','Sistem manual menyebabkan kesalahan tulis, hilangnya buku absensi, dan proses rekap yang lambat. Diperlukan sistem digital yang dapat diakses dan digunakan oleh guru untuk mencatat kehadiran dengan efisien dan menyajikan laporan secara otomatis.','2025-06-22 20:40:35','2025-06-22 20:40:35'),(6,20,'Bagaimana cara menyediakan sistem rekap kehadiran yang cepat dan akurat untuk keperluan evaluasi kedisiplinan siswa?','Tampilan sederhana, Panduan penggunaan tersedia, dan Akses melalui HP atau laptop','Guru mengalami kesulitan dalam menyiapkan laporan kehadiran untuk pihak sekolah karena sistem manual tidak efisien. Dibutuhkan sistem berbasis web dengan fitur pelaporan yang dapat digunakan dalam evaluasi kedisiplinan siswa.','2025-06-23 00:46:35','2025-06-23 00:46:35'),(7,21,'Bagaimana cara membuat sistem absensi digital yang dapat mempermudah guru dalam menyusun laporan kehadiran tanpa harus melakukan rekap manual?','Tidak perlu menghitung manual, Laporan rekap langsung tersedia, dan Mudah digunakan guru','Guru membutuhkan alat bantu pencatatan yang tidak menyulitkan. Masalah utama terletak pada waktu dan ketelitian. Sistem digital perlu dirancang dengan ramah pengguna dan rekap data otomatis.','2025-06-23 00:51:35','2025-06-23 00:51:35'),(8,22,'Bagaimana cara mengurangi risiko kehilangan data kehadiran siswa yang selama ini dicatat dalam buku?','Tersedia sistem pencatatan digital','Metode pencatatan manual tidak memiliki cadangan data. Dengan digitalisasi, semua data dapat disimpan secara aman dan diakses ulang kapan saja untuk keperluan audit maupun verifikasi.','2025-06-23 00:54:46','2025-06-23 00:54:46'),(9,23,'Bagaimana cara menghadirkan sistem absensi yang dapat secara otomatis menghitung persentase kehadiran setiap siswa?','Sistem menampilkan total hadir, alpa, izin dan Persentase muncul setelah periode mingguan','Guru kesulitan menghitung data kehadiran secara statistik. Sistem berbasis aplikasi dapat menghitung persentase secara real-time dan mengurangi risiko kesalahan manual.','2025-06-23 00:57:31','2025-06-23 00:57:31'),(10,24,'Bagaimana sistem absensi dapat membantu guru dan guru bimbingan konseling dalam pemantauan kedisiplinan siswa?','Status siswa ditampilkan: “Aktif” atau “Tidak Aktif”, Bisa digunakan guru sebagai evaluasi, dan Data kedisiplinan terintegrasi','Guru membutuhkan alat bantu pemantauan yang cepat. Sistem absensi berbasis data dan status aktif akan memudahkan proses evaluasi kinerja siswa terkait disiplin.','2025-06-23 01:00:43','2025-06-23 01:00:43'),(11,25,'Bagaimana merancang aplikasi absensi yang sederhana namun efektif bagi guru yang tidak memiliki latar belakang teknologi?','Tampilan sederhana, Panduan penggunaan tersedia, dan Akses melalui laptop atau komputer','Guru di SMK mungkin tidak semua paham dengan aplikasi kompleks. Maka, solusi absensi harus berbentuk aplikasi ringan, mudah digunakan, dan bisa dijalankan dari berbagai perangkat tanpa pelatihan teknis mendalam.','2025-06-23 01:03:38','2025-06-23 01:03:38'),(12,39,'Tentukan waktunya','Hari ini saya','Perjalanan menuju tempat parkir mobil wastafel','2025-07-04 08:20:06','2025-07-04 08:20:06');
/*!40000 ALTER TABLE `pgw_problems` ENABLE KEYS */;
UNLOCK TABLES;

