INSERT INTO `pjbl_phases` VALUES (1,'Tahap Orientasi Masalah','orientasi-masalah','Tulislah rumusan masalah, indikator pemecahan masalah dan analisis masalah sesuai studi kasus yang diberikan sebagai acuan untuk memulai project kelompok.','2025-06-08 03:12:27','2025-06-08 03:12:33'),(2,'Tahap Menyusun Rencana Proyek','menyusun-recana','Susun rencana pengerjaan proyek dan unggah dokumen pdf rencana proyek.','2025-06-08 03:12:27','2025-06-08 03:12:33'),(3,'Tahap Menyusun Jadwal Proyek','menyusun-jadwal','Susun jadwal pengerjaan proyek dan unggah dokumen pdf jadwal pengerjaan proyek.','2025-06-08 03:12:27','2025-06-08 03:12:33'),(4,'Tahap Pengumpulan Proyek dan Evaluasi','pengumpulan-evaluasi','Unggah dokumen pdf hasil pengerjaan proyek.','2025-06-08 03:12:27','2025-06-08 03:12:33'),(5,'Tahap Refleksi Pembelajaran','refleksi-pembelajaran','Jawablah pertanyaan berikut secara jujur dan reflektif.','2025-06-08 03:12:27','2025-06-08 03:12:33');
