/*!40000 ALTER TABLE `pjbl_questions` DISABLE KEYS */;
INSERT INTO `pjbl_questions` VALUES (3,NULL,'Pemrograman Terstruktur','<p><strong>Tujuan Pembelajaran :</strong></p>\r\n\r\n<ol>\r\n	<li>Siswa dapat menerapkan pengetahuan tentang kebutuhan representasi data untuk memilih struktur data statis yang tepat dalam sebuah pemrograman nyata</li>\r\n	<li>Siswa dapat menganalisis karakteristik tipe data untuk menentukan pemilihan dan penggunaan tipe data yang paling tepat dan efisien dalam menyelesaikan permasalahan logika program pada skenario pemrograman terstruktur menggunakan C++.</li>\r\n	<li>Siswa dapat mengevaluasi implementasi struktur kontrol dalam suatu program untuk mengidentifikasi potensi kesalahan logika dan merekomendasikan perbaikan berdasarkan pemahaman mendalam tentang logika pemrograman terstruktur.</li>\r\n	<li>Siswa dapat merancang dan membangun solusi pemrograman inovatif, yang sesuai untuk memenuhi kebutuhan fungsionalitas program atau menyelesaikan masalah pemrograman yang kompleks.</li>\r\n</ol>\r\n\r\n<p><strong>Petunjuk Pengerjaan:</strong></p>\r\n\r\n<ol>\r\n	<li>Kelompok terdiri dari 5-6 orang</li>\r\n	<li>Tulislah nama kelompok beserta nama anggota</li>\r\n	<li>Ketua kelompok bertanggung jawab mengkoordinir tugas setiap anggota kelompok</li>\r\n	<li>Jagalah ketertiban ketika berdiskusi dan melakukan praktik dengan hati-hati</li>\r\n</ol>\r\n\r\n<p><!-- notionvc: 61874b0a-6a22-4ae7-8b0d-4cf1f358e390 --></p>','<p><strong>Orientasi Masalah :</strong></p>\r\n\r\n<p>Di sebuah sekolah menengah kejuruan, guru wali kelas mengalami kesulitan dalam mencatat dan merekap kehadiran siswa setiap minggunya. Selama ini, proses absensi dilakukan secara manual dengan menulis kehadiran siswa di buku tulis. Namun, cara tersebut sering menimbulkan masalah: buku absensi hilang, angka kehadiran salah tulis, dan proses rekapitulasi ke dinas pendidikan memakan waktu lama.</p>\r\n\r\n<p>Selain itu, kepala sekolah ingin agar data kehadiran bisa langsung digunakan untuk mengevaluasi kedisiplinan siswa dan menjadi bahan pertimbangan saat pembagian penghargaan. Guru tersebut berharap ada sistem sederhana yang bisa membantunya mencatat kehadiran, menghitung persentase kehadiran siswa, dan menunjukkan status &ldquo;Aktif&rdquo; atau &ldquo;Tidak Aktif&rdquo; secara otomatis.</p>\r\n\r\n<p><strong>Link Permasalahan :</strong></p>\r\n\r\n<p><a href=\"https://www.hashmicro.com/id/blog/pentingnya-aplikasi-absensi-siswa-bagi-lembaga-pendidikan/\" target=\"_blank\">https://www.hashmicro.com/id/blog/pentingnya-aplikasi-absensi-siswa-bagi-lembaga-pendidikan/</a></p>','2025-06-08 06:35:33','2025-06-08 08:32:05');
/*!40000 ALTER TABLE `pjbl_questions` ENABLE KEYS */;
UNLOCK TABLES;

