INSERT INTO `questions` VALUES (1,1,'<p>Buatlah program dengan tahapan di bawah ini!</p>','[\"984128596.png\"]','Nilai x = 45\r\nNilai y = 15\r\nNilai rata = 30',15,0,'2025-04-15 13:57:17','2025-05-07 00:49:46'),(2,1,'<p>Buatlah program dengan tahapan di bawah ini!</p>','[\"385091290.png\"]','Nama Siswa = Rina Safitri\r\nUsia = 20\r\nJenis Kelamin = WANITA',15,0,'2025-04-15 14:00:28','2025-05-07 00:49:59'),(3,1,'<p>Buatlah program dengan tahapan di bawah ini!</p>','[\"418446179.png\"]','Nilai a = 12\r\nNilai b = 20\r\nNilai c = 40',15,0,'2025-04-15 14:03:03','2025-04-19 02:53:00'),(4,1,'<p>Buatlah program dengan tahapan di bawah ini!</p>','[\"924745271.png\"]','Umur kamu 18\r\nSudah boleh mengikuti ujian akhir',15,0,'2025-04-15 14:04:43','2025-04-19 02:53:09'),(5,1,'<p>Buatlah program dengan tahapan di bawah ini!</p>','[\"232739773.png\"]','Kode akses benar',15,0,'2025-04-15 14:06:24','2025-04-19 02:53:18'),(6,1,'<p>Buatlah program dengan tahapan di bawah ini!</p>','[\"2068188865.png\"]','Panjang = 8\r\nLebar = 5\r\nLuas = 40',15,0,'2025-04-15 14:08:37','2025-04-19 02:53:31'),(7,1,'<p>Buatlah program dengan tahapan di bawah ini!</p>','[\"1702340482.png\"]','Tinggi = 3\r\nDasar = 7',15,0,'2025-04-15 14:11:09','2025-04-19 02:53:40'),(8,1,'<p>Buatlah program dengan tahapan di bawah ini!</p>','[\"1666969371.png\"]','Tinggi = 7\r\nAlas = 8\r\nLuas = 56',15,0,'2025-04-15 14:14:52','2025-05-07 00:49:36'),(9,1,'<p>Buatlah program dengan tahapan di bawah ini!</p>','[\"125951103.png\"]','15 adalah kelipatan 3',15,0,'2025-04-15 14:18:17','2025-05-07 00:50:17'),(10,1,'<p>Buatlah program dengan tahapan di bawah ini!</p>','[\"1943984965.png\"]','Kilometer = 120\r\nMiles = 74.5645',15,0,'2025-04-15 14:20:14','2025-05-07 00:51:03'),(11,2,'<p>Buatlah program percabangan menggunakan IF untuk menentukan kriteria usia pendaftaran dengan ketentuan sebagai berikut!</p>','[\"1476881386.png\"]','Memenuhi syarat pendaftaran',15,0,'2025-04-15 14:22:41','2025-04-19 02:54:22'),(12,2,'<p>Buatlah program percabangan menggunakan IF dengan tahapan sebagai berikut!</p>','[\"408772062.png\"]','PIN benar',15,0,'2025-04-15 14:24:27','2025-04-19 02:54:29'),(13,2,'<p>Buatlah program percabangan menggunakan SWITCH-CASE dengan ketentuan sebagai berikut!</p>','[\"842374596.png\"]','Kategori sangat penting',15,0,'2025-04-15 14:25:48','2025-04-19 02:54:37'),(14,2,'<p>Buatlah program percabangan bersarang menggunakan IF untuk menentukan status keanggotaan berdasarkan usia dengan ketentuan sebagai berikut!</p>','[\"709142205.png\"]','Dewasa.',15,0,'2025-04-15 14:27:28','2025-04-19 02:54:44'),(15,2,'<p>Buatlah program percabangan menggunakan IF untuk menentukan apakah suatu bilangan ganjil atau genap dengan ketentuan sebagai berikut!</p>','[\"1188507270.png\"]','Bilangan genap',15,0,'2025-04-15 14:28:59','2025-04-19 02:54:54'),(16,2,'<p>Buatlah program perulangan menggunakan FOR untuk menampilkan tulisan &ldquo;Data ke-1&rdquo; menaik (increment) hingga menampilkan tulisan &ldquo;Data ke-10&rdquo; dengan ketentuan sebagai berikut!</p>','[\"473352263.png\"]','Data ke-1\r\nData ke-2\r\nData ke-3\r\nData ke-4\r\nData ke-5\r\nData ke-6\r\nData ke-7\r\nData ke-8\r\nData ke-9\r\nData ke-10',15,0,'2025-04-15 14:30:47','2025-04-19 02:55:08'),(17,2,'<p>Buatlah program perulangan menggunakan FOR untuk menampilkan tulisan &ldquo;Hitungan ke-10&rdquo; menurun (decrement) hingga menampilkan tulisan &ldquo;Hitungan ke-1&rdquo; dengan ketentuan sebagai berikut!</p>','[\"220146602.png\"]','Hitungan ke-10\r\nHitungan ke-9\r\nHitungan ke-8\r\nHitungan ke-7\r\nHitungan ke-6\r\nHitungan ke-5\r\nHitungan ke-4\r\nHitungan ke-3\r\nHitungan ke-2\r\nHitungan ke-1',15,0,'2025-04-15 14:32:22','2025-04-19 02:55:15'),(18,2,'<p>Buatlah program perulangan menggunakan do-while untuk menampilkan tulisan &ldquo;Belajar C++ 1&rdquo; menaik (increment) hingga menampilkan tulisan &ldquo;Belajar C++ 10&rdquo; dengan ketentuan sebagai berikut!</p>','[\"1012191764.png\"]','Belajar C++ 1\r\nBelajar C++ 2\r\nBelajar C++ 3\r\nBelajar C++ 4\r\nBelajar C++ 5\r\nBelajar C++ 6\r\nBelajar C++ 7\r\nBelajar C++ 8\r\nBelajar C++ 9\r\nBelajar C++ 10',15,0,'2025-04-15 14:33:54','2025-04-19 02:55:34'),(19,2,'<p>Buatlah program perulangan menggunakan do-while untuk menampilkan tulisan &ldquo;Latihan C++ 10&rdquo; menurun (decrement) hingga menampilkan tulisan &ldquo;Latihan C++ 1&rdquo; dengan ketentuan sebagai berikut!</p>','[\"392712520.png\"]','Latihan C++ 10\r\nLatihan C++ 9\r\nLatihan C++ 8\r\nLatihan C++ 7\r\nLatihan C++ 6\r\nLatihan C++ 5\r\nLatihan C++ 4\r\nLatihan C++ 3\r\nLatihan C++ 2\r\nLatihan C++ 1',15,0,'2025-04-15 14:35:22','2025-04-19 02:55:41'),(20,2,'<p>Buatlah program perulangan menggunakan <strong>FOR</strong> untuk menampilkan <strong>huruf A hingga I</strong> sesuai output di bawah dengan ketentuan sebagai berikut!</p>','[\"175404903.png\"]','ABCDEFGHI',15,0,'2025-04-15 14:37:53','2025-04-19 02:55:50'),(21,3,'<p>Buatlah program untuk menampilkan semua isi array!</p>','[\"1502922646.png\"]','10\r\n20\r\n30',15,0,'2025-04-15 14:40:26','2025-04-19 02:55:59'),(22,3,'<p>Buatlah program untuk menampilkan elemen tertentu dari array!</p>','[\"461292951.png\"]','Huruf ke-2: Z',15,0,'2025-04-15 14:42:30','2025-04-19 02:56:06'),(23,3,'<p>Buatlah program untuk mengubah nilai dalam array dan menampilkannya!</p>','[\"597589815.png\"]','1\r\n99\r\n3',15,0,'2025-04-15 14:43:37','2025-04-19 02:56:13'),(24,3,'<p>Buatlah program untuk menghitung total semua nilai dalam array!</p>','[\"661490966.png\"]','Total: 15',15,0,'2025-04-15 14:44:49','2025-04-19 02:56:19'),(25,3,'<p>Buatlah program untuk membuat 1 node pada linked list dan menampilkan isinya!</p>','[\"889566553.png\"]','Isi data node: 50',15,0,'2025-04-15 14:46:25','2025-04-19 02:56:26'),(27,4,'<p>Siswa X adalah seorang programmer yang diberi tugas oleh sekolah untuk membantu guru wali kelas mengevaluasi data nilai akhir dan kehadiran harian dari 5 siswa dalam 10 hari terakhir. Data akan dianalisis menggunakan struktur data statis (array) dengan bahasa pemrograman C++. Tugas kamu adalah membuat program sesuai kebutuhan pengguna, menggunakan tipe data dan struktur kontrol yang tepat, serta menampilkan hasil secara rapi dan mudah dipahami.</p>\r\n\r\n<p>Buatlah sistem manajemen nilai, kehadiran siswa, dan evaluasi hasil belajar dalam&nbsp;pemrograman C++</p>','[\"922022996.png\"]','Daftar Siswa:\r\nAndi - Nilai: 85, Kehadiran: 9\r\nBudi - Nilai: 70, Kehadiran: 7\r\nCitra - Nilai: 92, Kehadiran: 10\r\nDewi - Nilai: 65, Kehadiran: 6\r\nEko - Nilai: 78, Kehadiran: 8\r\n\r\nRata-rata nilai: 78\r\nSiswa dengan nilai tertinggi: Citra\r\nSiswa dengan kehadiran terbaik: Citra\r\n\r\nSiswa yang tidak lulus (nilai < 75):\r\n- Budi (70)\r\n- Dewi (65)\r\n\r\nSiswa dengan kehadiran < 80%:\r\n- Budi (7 hari hadir)\r\n- Dewi (6 hari hadir)',20,0,'2025-05-04 01:00:11','2025-05-07 00:29:59');
