INSERT INTO `result_details` VALUES (41,26,1,'#include <iostream>\n\nusing namespace std;\n\nint main() {\n    int x=10;\n    int y=25;\n    int z=x+y;\n\n    cout<<\"Sum of x+y = \" << z;\n}','Sum of x+y = 35',0,10,46,0,1,'2025-05-03 22:20:46','2025-05-03 22:20:46'),(42,27,27,'#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    const int JUMLAH_SISWA = 5;\n    const int JUMLAH_HARI = 10;\n\n    string nama[JUMLAH_SISWA] = {\"Andi\", \"Budi\", \"Citra\", \"Dewi\", \"Eko\"};\n    int nilai[JUMLAH_SISWA] = {85, 70, 92, 65, 78};\n    int kehadiran[JUMLAH_SISWA] = {9, 7, 10, 6, 8};\n\n    int totalNilai;\n    int indeksTertinggi;\n    int indeksKehadiranTerbaik;\n\n    totalNilai = 0;\n    indeksTertinggi = 0;\n    indeksKehadiranTerbaik = 0;\n\n    float rataRata;\n\n    cout << \"Daftar Siswa:\" << endl;\n    for (int i = 0; i < JUMLAH_SISWA; i++) {\n        cout << nama[i] << \" - Nilai: \" << nilai[i] << \", Kehadiran: \" << kehadiran[i] << endl;\n        totalNilai += nilai[i];\n\n        if (nilai[i] > nilai[indeksTertinggi]) {\n            indeksTertinggi = i;\n        }\n\n        if (kehadiran[i] > kehadiran[indeksKehadiranTerbaik]) {\n            indeksKehadiranTerbaik = i;\n        }\n    }\n\n    rataRata = totalNilai / (float)JUMLAH_SISWA;\n\n    cout << endl;\n    cout << \"Rata-rata nilai: \" << rataRata << endl;\n    cout << \"Siswa dengan nilai tertinggi: \" << nama[indeksTertinggi] << endl;\n    cout << \"Siswa dengan kehadiran terbaik: \" << nama[indeksKehadiranTerbaik] << endl;\n\n    cout << endl;\n    cout << \"Siswa yang tidak lulus (nilai < 75):\" << endl;\n\n    bool adaTidakLulus;\n    adaTidakLulus = false;\n\n    for (int i = 0; i < JUMLAH_SISWA; i++) {\n        if (nilai[i] < 75) {\n            cout << \"- \" << nama[i] << \" (\" << nilai[i] << \")\" << endl;\n            adaTidakLulus = true;\n        }\n    }\n\n    if (!adaTidakLulus) {\n        cout << \"- Tidak ada\" << endl;\n    }\n\n    cout << endl;\n    cout << \"Siswa dengan kehadiran < 80%:\" << endl;\n\n    bool adaKurangHadir;\n    adaKurangHadir = false;\n\n    for (int i = 0; i < JUMLAH_SISWA; i++) {\n        float persenHadir;\n        persenHadir = (kehadiran[i] / (float)JUMLAH_HARI) * 100;\n\n        if (persenHadir < 80) {\n            cout << \"- \" << nama[i] << \" (\" << kehadiran[i] << \" hari hadir)\" << endl;\n            adaKurangHadir = true;\n        }\n    }\n\n    if (!adaKurangHadir) {\n        cout << \"- Semua siswa hadir cukup\" << endl;\n    }\n\n    return 0;\n}','Daftar Siswa:\nAndi - Nilai: 85, Kehadiran: 9\nBudi - Nilai: 70, Kehadiran: 7\nCitra - Nilai: 92, Kehadiran: 10\nDewi - Nilai: 65, Kehadiran: 6\nEko - Nilai: 78, Kehadiran: 8\n\nRata-rata nilai: 78\nSiswa dengan nilai tertinggi: Citra\nSiswa dengan kehadiran terbaik: Citra\n\nSiswa yang tidak lulus (nilai < 75):\n- Budi (70)\n- Dewi (65)\n\nSiswa dengan kehadiran < 80%:\n- Budi (7 hari hadir)\n- Dewi (6 hari hadir)',1,29,54,0,1,'2025-05-04 07:57:15','2025-05-04 07:57:16'),(45,30,8,'#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    const int tinggi = 7;\n    const int alas = 8;\n    \n    int luas;\n    string opsi;\n    \n    luas = tinggi * alas;\n    opsi = \"Luas\";\n    \n    if (opsi == \"Luas\") {\n        cout << \"Tinggi = \" << tinggi << endl;\n        cout << \"Alas = \" << alas << endl;\n        cout << \"Luas = \" << luas << endl;\n    } else {\n        cout << \"Tinggi = \" << tinggi << endl;\n        cout << \"Alas = \" << alas << endl;\n    }\n    \n    return 0;\n}','Tinggi = 7\nAlas = 8\nLuas = 56',1,100,74,0,1,'2025-05-20 21:01:38','2025-05-20 21:01:38'),(46,31,15,'#include <iostream>\nusing namespace std;\n\nint main() {\n    int angka;\n    \n    angka = 12;\n    \n    if (angka % 2 == 0) {\n        cout << \"Bilangan genap\" << endl;\n    } else {\n        cout << \"Bilangan ganjil\" << endl;\n    }\n    \n    return 0;\n}','Bilangan genap',1,100,164,0,1,'2025-05-20 21:05:03','2025-05-20 21:05:03'),(47,32,10,'#include<iostream>\nusing namespace std;\n\nint main(){\n	float kilometer = 120;\n	float miles = kilometer * 0.621371;\n	string aksi = \"konversi\";\n	\n	if (aksi == \"konversi\"){\n		cout << \"Kilometer = \" << kilometer <<endl;\n		cout << \"Miles = \" << miles << endl;\n	} else{\n		cout << \"Hanya menghitung konversi\" << endl;\n	}\n}','Kilometer = 120\nMiles = 74.5645',1,100,533,0,1,'2025-05-20 21:09:44','2025-05-20 21:09:44'),(48,33,4,'#include<iostream>\n\nusing namespace std;\n\nint main () {\n	\nint umur = 18;\n\nif (umur >= 17) {\n	cout << \"umur kamu :\" << umur << endl;\n	cout << \"Sudah bole mengikuti ujian akhir\" << endl;\n} else {\n	cout << \"Umur kamu :\" << umur << endl;\n	cout << \"Belum memenuhi syarat untuk ujian akhir\" << endl;\n}\n\nreturn 0;\n	\n}','umur kamu :18\nSudah bole mengikuti ujian akhir',0,75,494,0,1,'2025-05-20 21:10:17','2025-05-20 21:10:17'),(49,34,10,'#include<iostream> \nusing namespace std;\n\nint main (){\n	float kilometer;\n	float miles;\n	string aksi;\n\n	kilometer = 120;\n	miles = kilometer * 0.621371;\n	aksi = \"konversi\";\n\n	if (aksi == \"konversi\") {\n	\n		cout << \"Kilometer = \" << kilometer << endl;\n		cout << \"Miles = \" << miles;\n		\n	} else {\n		\n		cout << miles;\n	}\n	\n	return 0;\n}','Kilometer = 120\nMiles = 74.5645',1,90,580,0,1,'2025-05-20 21:12:08','2025-05-20 21:12:08'),(50,35,1,'#include <iostream>\n\nint main() {\n    int x = 45;\n    int y = 15;\n    int rata;\n    \n    rata = (x + y) / 2;\n    \n    std::cout << \"Nilai x = \" << x << std::endl;\n    std::cout << \"Nilai y = \" << y << std::endl;\n    std::cout << \"Hasil rata = \" << rata << std::endl;\n    \n    return 0;\n}','Nilai x = 45\nNilai y = 15\nHasil rata = 30',0,38,502,0,1,'2025-05-20 21:12:49','2025-05-20 21:12:49'),(51,36,5,'#include <iostream>\n\nusing namespace std;\n\nint main() {\n\n    string kode_akses = \"1234\";\n\n\n    if (kode_akses == \"1234\") {\n\n        cout << \"Kode akses benar\" << endl;\n\n    } else {\n\n        cout << \"Kode akses salah\" << endl;\n\n    }\n\n    return 0;\n\n}','Kode akses benar',1,100,601,0,1,'2025-05-20 21:12:54','2025-05-20 21:12:54'),(52,37,5,'#include <iostream>\n#include <string>\n\nusing namespace std;\n\nint main() {\n\n    string kodeakses;\n\n    kodeakses = \"1234\";\n\n    if (kodeakses == \"1234\") {\n        cout << \"Kode akses benar\" << endl;\n    } else {\n        cout << \"Kode akses salah\" << endl;\n    }\n\n    return 0;\n}','Kode akses benar',1,56,605,0,1,'2025-05-20 21:13:08','2025-05-20 21:13:08'),(53,38,4,'#include <iostream>\n\nusing namespace std;\n\nint main(){\n	int umur=18;\n	\n	if (umur >= 17){\n		cout << \"Umur kamu \" << umur << endl;\n        cout << \"Sudah boleh mengikuti ujian akhir\" << endl;\n	}\n}','Umur kamu 18\nSudah boleh mengikuti ujian akhir',1,81,625,0,1,'2025-05-20 21:13:18','2025-05-20 21:13:18'),(54,39,4,'#include <iostream>\nusing namespace std;\n\nint main() {\n    int umur;\n    \n    // Inisialisasi\n    umur = 18;\n    \n    // Kontrol percabangan dengan if\n    if (umur >= 17) {\n        cout << \"Umur kamu \" << umur << endl;\n        cout << \"Sudah boleh mengikuti ujian akhir\" << endl;\n    } else {\n        cout << \"Umur kamu \" << umur << endl;\n        cout << \"Belum memenuhi syarat untuk ujian akhir\" << endl;\n    }\n    \n    return 0;\n}','Umur kamu 18\nSudah boleh mengikuti ujian akhir',1,100,418,0,1,'2025-05-20 21:13:24','2025-05-20 21:13:24'),(56,41,2,'#include <iostream>\nusing namespace std;\n\nint main() {\n   \n    string nama_siswa = \"Rina Safitri\";\n    int usia = 20;\n    char kelamin = \'P\';\n\n    \n    cout << \"Nama Siswa = \" << nama_siswa << endl;\n    cout << \"Usia = \" << usia << endl;\n\n  \n    if (kelamin == \'P\') {\n        cout << \"Jenis Kelamin = WANITA\" << endl;\n    } else {\n        cout << \"Jenis Kelamin = LAKI-LAKI\" << endl;\n    }\n\n    return 0;\n}','Nama Siswa = Rina Safitri\nUsia = 20\nJenis Kelamin = WANITA',1,85,552,0,1,'2025-05-20 21:13:34','2025-05-20 21:13:34'),(57,42,5,'#include<iostream>\n#include<string>\nusing namespace std;\n\nint main(){\n	\n	string kode_akses;\n	kode_akses = \"1234\";\n\n	if (kode_akses == \"1234\") {\n		cout << \"Kode akses Benar\";\n	}\n	\n	else {\n		cout << \"Kode akses Salah\";\n	}\n	\n}','Kode akses Benar',1,100,737,0,1,'2025-05-20 21:14:57','2025-05-20 21:14:57'),(58,43,1,'#include <iostream>\n\nint main() {\n    // Deklarasi variabel\n    int x, y, rata;\n    char jawaban;\n\n    // Inisialisasi nilai\n    x = 45;\n    y = 15;\n    jawaban = \'T\';\n    rata = (x + y) / 2;\n\n    // Percabangan\n    if (jawaban == \'T\') {\n        printf(\"Nilai x: %d\\n\", x);\n        printf(\"Nilai y: %d\\n\", y);\n        printf(\"Nilai rata-rata: %d\\n\", rata);\n    } else {\n        printf(\"Nilai x: %d\\n\", x);\n        printf(\"Nilai y: %d\\n\", y);\n    }\n\n    return 0;\n}','Nilai x: 45\nNilai y: 15\nNilai rata-rata: 30',0,65,356,0,1,'2025-05-20 21:14:59','2025-05-20 21:15:00'),(60,45,8,'#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    const int tinggi = 7;\n    const int alas = 8;\n    int luas = tinggi * alas;\n    string opsi = \"Luas\";\n\n    if (opsi == \"Luas\") {\n        cout << \"Tinggi = \" << tinggi << endl;\n        cout << \"Alas = \" << alas << endl;\n        cout << \"Luas = \" << luas << endl;\n    } else {\n        cout << \"Tinggi = \" << tinggi << endl;\n        cout << \"Alas = \" << alas << endl;\n    }\n\n    return 0;\n}','Tinggi = 7\nAlas = 8\nLuas = 56',1,100,82,0,1,'2025-05-20 21:15:51','2025-05-20 21:15:51'),(61,46,2,'#include <iostream>\nusing namespace std;\n\nint main() {\n    \n    string nama_siswa = \"Rina Safitri\";\n    int usia = 20;\n    char kelamin = \'P\';\n\n    \n    cout << \"Nama Siswa = \" << nama_siswa << endl;\n    cout << \"Usia = \" << usia << endl;\n\n    \n    if (kelamin == \'P\') {\n        cout << \"Jenis Kelamin = WANITA\" << endl;\n    } else {\n        cout << \"Jenis Kelamin = LAKI-LAKI\" << endl;\n    }\n\n    return 0;\n}','Nama Siswa = Rina Safitri\nUsia = 20\nJenis Kelamin = WANITA',1,85,538,0,1,'2025-05-20 21:15:59','2025-05-20 21:15:59'),(62,47,1,'#include<iostream>\nusing namespace std;\nint main() {\nint x = 45;\nint y = 15;\nint rata = x + y / 2;\nchar nama = \'T\';\n\nif (nama == \'T\') {\ncout << \"Nilai x:\" << x << endl;\ncout << \"Nilai y:\" << y << endl;\ncout << \"Nilai rata:\" << rata << endl;\n}else {\ncout << \"Nilai x:\" << x << endl;\ncout << \"Nilai y:\" << y << endl;\n}\nreturn 0;\n}','Nilai x:45\nNilai y:15',0,36,907,0,1,'2025-05-20 21:16:09','2025-05-20 21:16:09'),(63,48,10,'#include <iostream>\n#include <string>\n#include <iomanip>\n\nint main() {\n    float kilometer;\n    float miles;\n    std::string aksi;\n\n    kilometer = 120;\n    miles = kilometer * 0.621371;\n    aksi = \"konversi\";\n\n    if (aksi == \"konversi\") {\n\n        std::cout << \"Kilometer = \" << kilometer << std::endl;\n        std::cout << \"Miles = \" << std::fixed << std::setprecision(4) << miles << std::endl;\n    } else {\n\n        std::cout << \"Hanya menghitung konversi\" << std::endl;\n    }\n    \n    return 0;\n}','Kilometer = 120\nMiles = 74.5645',1,70,125,0,1,'2025-05-20 21:16:12','2025-05-20 21:16:12'),(64,49,17,'#include <iostream>\nusing namespace std;\n\nint main() {\n    // Deklarasi dan inisialisasi variabel\n    int angka = 1;\n    int maksimum = 10;\n\n    // Perulangan menurun dari maksimum ke angka\n    for (int i = maksimum; i >= angka; i--) {\n        cout << \"Hitungan ke-\" << i << endl;\n    }\n\n    return 0;\n}','Hitungan ke-10\nHitungan ke-9\nHitungan ke-8\nHitungan ke-7\nHitungan ke-6\nHitungan ke-5\nHitungan ke-4\nHitungan ke-3\nHitungan ke-2\nHitungan ke-1',1,46,41,0,1,'2025-05-20 21:16:13','2025-05-20 21:16:13'),(65,50,9,'#include<iostream>\nusing namespace std;\nint main(){\nint angka = 15;\nif(angka % 3 == 0){\n cout<<angka<<\" adalah kelipatan 3\"<<endl;\n}else{\ncout<<\"bukan kelipatan 3\"<<endl;\n}\n}','15 adalah kelipatan 3',1,90,937,0,1,'2025-05-20 21:16:50','2025-05-20 21:16:50'),(66,51,16,'#include <iostream>\n\nusing namespace std;\n\nint main() {\n    int indeks = 1;\n    int jumlah = 10;\n\n    for (indeks = 1; indeks <= jumlah; indeks++) {\n        cout << \"Data ke-\" << indeks << endl;\n    }\n    return 0;\n}','Data ke-1\nData ke-2\nData ke-3\nData ke-4\nData ke-5\nData ke-6\nData ke-7\nData ke-8\nData ke-9\nData ke-10',1,64,210,0,1,'2025-05-20 21:17:16','2025-05-20 21:17:16'),(67,52,12,'#include <iostream>\nusing namespace std;\n\nint main() {\n    // Deklarasi dan inisialisasi variabel\n    int angkaPIN = 7890;\n\n    // Kontrol percabangan\n    if (angkaPIN == 7890) {\n        cout << \"PIN benar\" << endl;\n    } else {\n        cout << \"PIN salah\" << endl;\n    }\n\n    return 0;\n}','PIN benar',1,100,155,0,1,'2025-05-20 21:17:19','2025-05-20 21:17:19'),(68,53,20,'#include <iostream>\nusing namespace std;\n\nint main() {\n   \n    char karakter = \'A\';\n\n    for (int i = 0; i < 9; i++) {\n        cout << karakter << \" \";\n        karakter++;\n    }\n\n    return 0;\n}','A B C D E F G H I',1,80,189,0,1,'2025-05-20 21:17:19','2025-05-20 21:17:19'),(70,55,20,'#include <iostream>\nusing namespace std;\n\nint main() {\n    char karakter = \'A\';\n\n    for (int i = 0; i < 9; i++) {\n        cout << karakter;\n        karakter++;\n    }\n\n    return 0;\n}','ABCDEFGHI',1,100,84,0,1,'2025-05-20 21:17:40','2025-05-20 21:17:40'),(71,56,11,'#include <iostream>\n\nint main() {\n\n    double usia;\n    \n    usia = 18;\n    \n    if (usia >= 17) {\n\n        std::cout << \"Memenuhi syarat pendaftaran\" << std::endl;\n    } else {\n\n        std::cout << \"Belum memenuhi syarat\" << std::endl;\n    }\n    \n    return 0;\n}','Memenuhi syarat pendaftaran',1,70,75,0,1,'2025-05-20 21:17:41','2025-05-20 21:17:41'),(72,57,21,'#include <iostream>\nusing namespace std;\n\nint main() {\n    // Deklarasi dan inisialisasi array\n