 21:29:55','2025-05-20 21:29:55'),(105,90,13,'#include<iostream>\nusing namespace std;\nint main() {\n	char kategori = \'X\';\n	if (kategori == \'X\'){\n		cout << \"Kategori sangat penting\";\n	}\n 	else if (kategori == \'Y\'){\n		cout << \"Kategori penting\";\n	}\n	else if (kategori == \'Z\'){\n		cout << \"Kategori biasa\";\n	}\n	else{\n		cout<< \"Kategori tidak bisa dikenal\";\n	}\n}','Kategori sangat penting',1,58,464,0,1,'2025-05-20 21:31:33','2025-05-20 21:31:33'),(106,91,13,'#include <iostream>\nusing namespace std;\n\nint main() {\n    // Deklarasi dan inisialisasi variabel\n    char kategori = \'X\';\n\n    // Kontrol percabangan dengan switch-case\n    switch (kategori) {\n        case \'X\':\n            cout << \"Kategori sangat penting\" << endl;\n            break;\n        case \'Y\':\n            cout << \"Kategori penting\" << endl;\n            break;\n        case \'Z\':\n            cout << \"Kategori biasa\" << endl;\n            break;\n        default:\n            cout << \"Kategori tidak dikenal\" << endl;\n            break;\n    }\n\n    return 0;\n}','Kategori sangat penting',1,100,264,0,1,'2025-05-20 21:31:37','2025-05-20 21:31:37'),(107,92,4,'#include <iostream>\nusing namespace std;\n\nint main() {\n	int umur;\n	std::cout << \"18: \";\n	std::cin >> umur:\n	\n	if (umur >= 17) {\n		std::cout << \"16\" <<\numur <<	std::endl;\n		std::cout << \"sudah boleh mengikuti ujian akhir\" std::endl;	\n	} else {\n		std::cout << \"16\" <<\numur << std::endl;\n		std::cout << \"belum memenuhi syarat untuk ujian akhir\" <<\n		std::endl;	\n	}\n	\n}','[COMPILE ERROR]\n682d5739ee18c.cpp: In function \'int main()\':\n682d5739ee18c.cpp:7:25: error: expected \';\' before \':\' token\n    7 |         std::cin >> umur:\n      |                         ^\n      |                         ;\n682d5739ee18c.cpp:13:11: error: \'else\' without a previous \'if\'\n   13 |         } else {\n      |           ^~~~',0,45,1588,0,0,'2025-05-20 21:31:55','2025-05-20 21:31:55'),