\n	int alas = 8;\n	\n	int luas;\n	string opsi;\n	\n	luas = tinggi*alas;\n	opsi = \"Luas\";\n	\n	if (opsi == \"Luas\"){\n		cout << \"Tinggi: \" << tinggi << endl;\n        cout << \"Alas: \" << alas << endl;\n        cout << \"Luas: \" << luas << endl;\n	}else {\n        cout << \"Tinggi: \" << tinggi << endl;\n        cout << \"Alas: \" << alas << endl;\n    }\n\n}','Tinggi: 7\nAlas: 8\nLuas: 56',0,47,972,0,1,'2025-05-21 06:56:15','2025-05-21 06:56:15'),(121,106,15,'#include<iostream>\nusing namespace std;\n\nint main(){\n	\n	int angka = 12;\n	\n	\n	if (angka % 2 == 0){\n		cout << \"Bilangan genap\" << endl;\n	} else{\n		cout << \"Bilangan ganjil\" << endl;\n	}\n	\n}','Bilangan genap',1,100,200,0,1,'2025-05-25 18:17:22','2025-05-25 18:17:23'),(122,107,1,'#include <iostream>\n\nusing namespace std;\n\nint main() {\n\n    // Deklarasi dan inisialisasi variabel\n\n    int x = 45;\n\n    int y = 15;\n\n    char jawaban = \'T\';\n\n    int rata = (x + y) / 2;\n\n    // Percabangan if\n\n    if (jawaban == \'T\') {\n\n        cout << \"Nilai x: \" << x << endl;\n\n        cout << \"Nilai y: \" << y << endl;\n\n        cout << \"Nilai rata: \" << rata << endl;\n\n    } else {\n\n        cout << \"Nilai x: \" << x << endl;\n\n        cout << \"Nilai y: \" << y << endl;\n\n    }\n\n    return 0;\n\n}','Nilai x: 45\nNilai y: 15\nNilai rata: 30',0,65,128,0,1,'2025-05-25 18:17:58','2025-05-25 18:17:58'),(123,108,16,'#include <iostream> \nusing namespace std;\n\nint main() {\n    int data; \n\n    for (int j = 1; j <= 10; j++) {\n        data = j; \n        cout << \"Data ke-\" << data << endl;\n    }\n\n    return 0;\n}','Data ke-1\nData ke-2\nData ke-3\nData ke-4\nData ke-5\nData ke-6\nData ke-7\nData ke-8\nData ke-9\nData ke-10',1,28,288,0,1,'2025-05-25 18:18:38','2025-05-25 18:18:38'),(124,109,14,'#include<iostream>\nusing namespace std;\n\nint main(){\n	int usia;\n	\n	usia = 30;\n	\n	if (usia > 18){\n		cout  << \"Dewasa.\" << endl;\n	}else if (usia >= 60){\n		cout << \"Senior\" << endl;\n	}else{\n		cout << \"Anak-anak atau Remaja\" << endl;\n	}\n\n		\n}','Dewasa.',1,100,472,0,1,'2025-05-25 18:20:15','2025-05-25 18:20:15'),(125,110,2,'#include <iostream>\nusing namespace std;\n\nint main() {\n    string nama_siswa = \"Rina Safitri\";\n    int usia = 20;\n    char kelamin = \'P\';\n\n    cout << \"Nama Siswa  : \" << nama_siswa << endl;\n    cout << \"Usia        : \" << usia << \" tahun\" << endl;\n\n    if (kelamin == \'P\') {\n        cout << \"Jenis Kelamin: WANITA\" << endl;\n    } else {\n        cout << \"Jenis Kelamin: LAKI-LAKI\" << endl;\n    }\n\n    return 0;\n}','Nama Siswa  : Rina Safitri\nUsia        : 20 tahun\nJenis Kelamin: WANITA',0,47,150,0,1,'2025-05-25 18:20:30','2025-05-25 18:20:30'),(126,111,20,'#include <stdio.h>\n\nint main() {\n    char karakter = \'A\'; // Inisialisasi karakter mulai dari \'A\'\n\n    for (int i = 0; i < 9; i++) { // Perulangan sebanyak 9 kali (A sampai I)\n        printf(\"%c \", karakter); // Tampilkan karakter ke samping dengan spasi\n        karakter++; // Naik ke huruf berikutnya\n    }\n\n    return 0;\n}','A B C D E F G H I',1,80,34,0,1,'2025-05-25 18:21:36','2025-05-25 18:21:36'),(127,112,25,'#include <iostream>\nusing namespace std;\n\n\nstruct Node {\n    int data;       \n  	Node*next;  \n};\n\nint main() {\n   \n    Node* node1;\n    node1 = new Node;\n    node1->data = 50;\n    node1->next = nullptr;\n    cout << \"Isi data node1: \" << node1->data << endl;\n    delete node1;\n\n    return 0;\n}','Isi data node1: 50',0,70,251,0,1,'2025-05-25 18:21:46','2025-05-25 18:21:46'),(128,113,14,'#include <iostream>\nusing namespace std;\n\nint main() {\n    int usia = 30;\n\n    if (usia > 18) {\n        cout << \"Dewasa.\" << endl;\n\n        if (usia >= 60) {\n            cout << \"Senior\" << endl;\n        }\n    } else {\n        cout << \"Anak-anak atau Remaja\" << endl;\n    }\n\n    return 0;\n}','Dewasa.',1,100,159,0,1,'2025-05-25 18:23:37','2025-05-25 18:23:37'),(129,114,21,'#include <stdio.h>\n\nint main() {\n\n    int angka[] = {10, 20, 30}; // Deklarasi array\n\n    int i = 0; // Inisialisasi variabel i\n\n    // Perulangan untuk menampilkan seluruh elemen array\n\n    for(i = 0; i < 3; i++) {\n\n        printf(\"%d\\n\", angka[i]); // Tampilkan elemen array, tiap elemen di baris baru\n\n    }\n\n    return 0;\n\n}','10\n20\n30',1,70,63,0,1,'2025-05-25 18:23:39','2025-05-25 18:23:39'),(130,115,23,'#include <iostream>\nusing namespace std;\n\nint main() {\n    // Deklarasi array\n    int angka[3] = {1, 2, 3};\n\n    // Deklarasi dan inisialisasi variabel\n    int i = 0;\n\n    // Ubah elemen pada indeks ke-1 menjadi 99\n    angka[1] = 99;\n\n    // Perulangan untuk menampilkan semua elemen array\n    for(i = 0; i < 3; i++) {\n        cout << angka[i] << endl;\n    }\n\n    return 0;\n}','1\n99\n3',1,100,106,0,1,'2025-05-25 18:24:40','2025-05-25 18:24:40'),(131,116,23,'#include <iostream>\nusing namespace std;\n\nint main() {\n    // Deklarasi dan inisialisasi array\n    int angka[] = {1, 2, 3};\n\n    // Ubah elemen indeks ke-1 menjadi 99\n    angka[1] = 99;\n\n    // Tampilkan seluruh elemen array\n    for (int i = 0; i < 3; i++) {\n        cout << angka[i] << endl; // Setiap elemen ditampilkan dalam baris baru\n    }\n\n    return 0;\n}','1\n99\n3',1,80,59,0,1,'2025-05-25 18:25:02','2025-05-25 18:25:02'),(132,117,1,'#include <iostream>\nusing namespace std;\n\nint main() {\n    int x = 45;\n    int y = 15;\n    char jawaban = \'T\';\n    int rata = (x + y) / 2;\n\n    if (jawaban == \'T\') {\n        cout << \"Nilai x: \" << x << endl;\n        cout << \"Nilai y: \" << y << endl;\n        cout << \"Nilai rata-rata: \" << rata << endl;\n    } else {\n        cout << \"Nilai x: \" << x << endl;\n        cout << \"Nilai y: \" << y << endl;\n    }\n\n    return 0;\n}','Nilai x: 45\nNilai y: 15\nNilai rata-rata: 30',0,65,323,0,1,'2025-05-25 18:25:45','2025-05-25 18:25:45'),(133,118,9,'#include <iostream>\nusing namespace std;\n\nint main() {\n    // Deklarasi dan inisialisasi variabel\n    int angka = 15;\n\n    // Kontrol percabangan menggunakan if\n    if (angka % 3 == 0) {\n        cout << angka << \" adalah kelipatan 3\" << endl;\n    } else {\n        cout << angka << \" bukan kelipatan 3\" << endl;\n    }\n\n    return 0;\n}','15 adalah kelipatan 3',1,100,89,0,1,'2025-05-25 18:26:08','2025-05-25 18:26:08'),(134,119,23,'#include<iostream>\nusing namespace std;\n\nint main (){\n	int angka[] = {1,2,3};\n	angka[1] = 99;\n	\n\n	int i = 0;\n	\n	for(i = 0; i < 3; ++i){\n		cout << angka[i] << endl;\n	}\n	\n}','1\n99\n3',1,100,593,0,1,'2025-05-25 18:27:35','2025-05-25 18:27:35'),(135,120,6,'#include<iostream>\nusing namespace std;\n\nint main() {\n	int panjang = 8;\n	int lebar = 5;\n	double Luas = panjang * lebar;\n	string jenis = \"persegi panjang\";\n	\n	if(jenis == \"persegi panjang\"){\n		cout<<\"panjang = \"<< panjang <<endl;\n		cout<<\"lebar = \"<< lebar <<endl;\n		cout<<\"Luas = \"<< Luas <<endl;\n	} else {\n		cout<<\"panjang = \"<< panjang <<endl;\n		cout<<\"lebar = \"<< lebar <<endl;\n	}\n}','panjang = 8\nlebar = 5\nLuas = 40',1,100,549,0,1,'2025-05-25 18:29:57','2025-05-25 18:29:57'),(136,121,20,'#include <iostream>\nusing namespace std;\n\nint main () {\n	\n	char karakter[9] = {\'A\',\'B\',\'C\',\'D\',\'E\',\'F\',\'G\',\'H\',\'I\'};\n	\n	for (int i=0; i<9; i++) {\n		cout << karakter[i] ;\n	}\n	\n}','ABCDEFGHI',1,45,1693,0,1,'2025-05-25 18:49:46','2025-05-25 18:49:46'),(137,122,27,'#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    // Deklarasi dan Inisialisasi Variabel\n    const int JUMLAH_SISWA = 5;\n    const int JUMLAH_HARI = 10;\n\n    string nama[JUMLAH_SISWA] = {\"Andi\", \"Budi\", \"Citra\", \"Dewi\", \"Eko\"};\n    int nilai[JUMLAH_SISWA] = {85, 70, 92, 65, 78};\n    int kehadiran[JUMLAH_SISWA] = {9, 7, 10, 6, 8};\n\n    int totalNilai = 0;\n    int indeksTertinggi = 0;\n    int indeksKehadiranTerbaik = 0;\n    float rataRata;\n\n    // Menampilkan Data dan Melakukan Perhitungan\n    cout << \"Daftar Siswa:\" << endl;\n    for (int i = 0; i < JUMLAH_SISWA; i++) {\n        cout << nama[i] << \" - Nilai: \" << nilai[i] << \", Kehadiran: \" << kehadiran[i] << endl;\n        totalNilai += nilai[i];\n\n        if (nilai[i] > nilai[indeksTertinggi]) {\n            indeksTertinggi = i;\n        }\n\n        if (kehadiran[i] > kehadiran[indeksKehadiranTerbaik]) {\n            indeksKehadiranTerbaik = i;\n        }\n    }\n\n    // Menghitung Nilai Rata-rata\n    rataRata = static_cast<float>(totalNilai) / JUMLAH_SISWA;\n\n    // Menampilkan Hasil Perhitungan\n    cout << endl;\n    cout << \"Rata-rata nilai: \" << rataRata << endl;\n    cout << \"Siswa dengan nilai tertinggi: \" << nama[indeksTertinggi] << endl;\n    cout << \"Siswa dengan kehadiran terbaik: \" << nama[indeksKehadiranTerbaik] << endl;\n\n    // Identifikasi Siswa yang Tidak Lulus\n    cout << endl << \"Siswa yang tidak lulus (nilai < 75):\" << endl;\n    bool adaTidakLulus = false;\n    for (int i = 0; i < JUMLAH_SISWA; i++) {\n        if (nilai[i] < 75) {\n            cout << \"- \" << nama[i] << \" (\" << nilai[i] << \")\" << endl;\n            adaTidakLulus = true;\n        }\n    }\n    if (!adaTidakLulus) {\n        cout << \"- Tidak ada\" << endl;\n    }\n\n    // Identifikasi Siswa dengan Kehadiran Kurang\n    cout << endl << \"Siswa dengan kehadiran < 80%:\" << endl;\n    bool adaKurangHadir = false;\n    for (int i = 0; i < JUMLAH_SISWA; i++) {\n        float persenHadir = (kehadiran[i] / static_cast<float>(JUMLAH_HARI)) * 100;\n        if (persenHadir < 80) {\n            cout << \"- \" << nama[i] << \" (\" << kehadiran[i] << \" hari hadir)\" << endl;\n            adaKurangHadir = true;\n        }\n    }\n    if (!adaKurangHadir) {\n        cout << \"- Semua siswa hadir cukup\" << endl;\n    }\n\n    return 0;\n}','Daftar Siswa:\nAndi - Nilai: 85, Kehadiran: 9\nBudi - Nilai: 70, Kehadiran: 7\nCitra - Nilai: 92, Kehadiran: 10\nDewi - Nilai: 65, Ke