58,143,27,'#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    // Deklarasi dan Inisialisasi Variabel\n    const int JUMLAH_SISWA = 5;\n    const int JUMLAH_HARI = 10;\n    string nama[JUMLAH_SISWA] = {\"Andi\", \"Budi\", \"Citra\", \"Dewi\", \"Eko\"};\n    int nilai[JUMLAH_SISWA] = {85, 70, 92, 65, 78};\n    int kehadiran[JUMLAH_SISWA] = {9, 7, 10, 6, 8};\n    int totalNilai = 0;\n    int indeksTertinggi = 0;\n    int indeksKehadiranTerbaik = 0;\n    float rataRata;\n\n    // Menampilkan Data dan Melakukan Perhitungan\n    cout << \"Daftar Siswa:\" << endl;\n    for (int i = 0; i < JUMLAH_SISWA; i++) {\n        cout << nama[i] << \" - Nilai: \" << nilai[i] << \", Kehadiran: \" << kehadiran[i] << endl;\n        totalNilai += nilai[i];\n        \n        if (nilai[i] > nilai[indeksTertinggi]) {\n            indeksTertinggi = i;\n        }\n        \n        if (kehadiran[i] > kehadiran[indeksKehadiranTerbaik]) {\n            indeksKehadiranTerbaik = i;\n        }\n    }\n\n    // Menghitung Nilai Rata-rata\n    rataRata = static_cast<float>(totalNilai) / JUMLAH_SISWA;\n\n    // Menampilkan Hasil Perhitungan\n    cout << endl;\n    cout << \"Rata-rata nilai: \" << rataRata << endl;\n    cout << \"Siswa dengan nilai tertinggi: \" << nama[indeksTertinggi] << endl;\n    cout << \"Siswa dengan kehadiran terbaik: \" << nama[indeksKehadiranTerbaik] << endl;\n\n    // Identifikasi Siswa yang Tidak Lulus\n    cout << endl << \"Siswa yang tidak lulus (nilai < 75):\" << endl;\n    bool adaTidakLulus = false;\n    for (int i = 0; i < JUMLAH_SISWA; i++) {\n        if (nilai[i] < 75) {\n            cout << \"- \" << nama[i] << \" (\" << nilai[i] << \")\" << endl;\n            adaTidakLulus = true;\n        }\n    }\n    if (!adaTidakLulus) {\n        cout << \"- Tidak ada\" << endl;\n    }\n\n    // Identifikasi Siswa dengan Kehadiran Kurang\n    cout << endl << \"Siswa dengan kehadiran < 80%:\" << endl;\n    bool adaKurangHadir = false;\n    for (int i = 0; i < JUMLAH_SISWA; i++) {\n        float persenHadir = (kehadiran[i] / static_cast<float>(JUMLAH_HARI)) * 100;\n        if (persenHadir < 80) {\n            cout << \"- \" << nama[i] << \" (\" << kehadiran[i] << \" hari hadir)\" << endl;\n            adaKurangHadir = true;\n        }\n    }\n    if (!adaKurangHadir) {\n        cout << \"- Semua siswa hadir cukup\" << endl;\n    }\n\n    return 0;\n}','Daftar Siswa:\nAndi - Nilai: 85, Kehadiran: 9\nBudi - Nilai: 70, Kehadiran: 7\nCitra - Nilai: 92, Kehadiran: 10\nDewi - Nilai: 65, Kehadiran: 6\nEko - Nilai: 78, Kehadiran: 8\n\nRata-rata nilai: 78\nSiswa dengan nilai tertinggi: Citra\nSiswa dengan kehadiran terbaik: Citra\n\nSiswa yang tidak lulus (nilai < 75):\n- Budi (70)\n- Dewi (65)\n\nSiswa dengan kehadiran < 80%:\n- Budi (7 hari hadir)\n- Dewi (6 hari hadir)',1,25,1722,0,1,'2025-05-25 19:36:21','2025-05-25 19:36:21'),(159,144,27,'#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n\n	const int JUMLAH_SISWA = 5;\n    const int JUMLAH_HARI = 10;\n\n    string nama[JUMLAH_SISWA] = {\"Andi\", \"Budi\", \"Citra\", \"Dewi\", \"Eko\"};\n    int nilai[JUMLAH_SISWA] = {85, 70, 92, 65, 78};\n    int kehadiran[JUMLAH_SISWA] = {9, 7, 10, 6, 8};\n\n    int totalNilai = 0;\n    int indeksTertinggi = 0;\n    int indeksKehadiranTerbaik = 0;\n    float rataRata;\n\n\n	cout << \"Daftar Siswa:\\n\";\n    for (int i = 0; i < JUMLAH_SISWA; ++i) {\n        cout << nama[i] << \" - Nilai: \" << nilai[i]\n             << \", Kehadiran: \" << kehadiran[i] << endl;\n\n        totalNilai += nilai[i];\n\n        if (nilai[i] > nilai[indeksTertinggi]) {\n            indeksTertinggi = i;\n        }\n\n        if (kehadiran[i] > kehadiran[indeksKehadiranTerbaik]) {\n            indeksKehadiranTerbaik = i;\n        }\n    }\n\n \n	rataRata = (float)totalNilai / JUMLAH_SISWA;\n\n\n	cout << \"\\nRata-rata nilai: \" << rataRata << endl;\n    cout << \"Siswa dengan nilai tertinggi: \" << nama[indeksTertinggi] << endl;\n    cout << \"Siswa dengan kehadiran terbaik: \" << nama[indeksKehadiranTerbaik] << endl;\n\n\n	cout << \"\\nSiswa yang tidak lulus (nilai < 75):\\n\";\n    bool adaTidakLulus = false;\n    for (int i = 0; i < JUMLAH_SISWA; ++i) {\n        if (nilai[i] < 75) {\n            cout << \"- \" << nama[i] << \" (\" << nilai[i] << \")\\n\";\n            adaTidakLulus = true;\n        }\n    }\n    if (!adaTidakLulus) {\n        cout << \"- Tidak ada\\n\";\n    }\n\n\n	cout << \"\\nSiswa dengan kehadiran < 80%:\\n\";\n    bool adaKurangHadir = false;\n    for (int i = 0; i < JUMLAH_SISWA; ++i) {\n        float persenHadir = (kehadiran[i] / (float)JUMLAH_HARI) * 100;\n        if (persenHadir < 80) {\n            cout << \"- \" << nama[i] << \" (\" << kehadiran[i] << \" hari hadir)\\n\";\n            adaKurangHadir = true;\n        }\n    }\n    if (!adaKurangHadir) {\n        cout << \"- Semua siswa hadir cukup\\n\";\n    }\n\n    return 0;\n}','Daftar Siswa:\nAndi - Nilai: 85, Kehadiran: 9\nBudi - Nilai: 70, Kehadiran: 7\nCitra - Nilai: 92, Kehadiran: 10\nDewi - Nilai: 65, Kehadiran: 6\nEko - Nilai: 78, Kehadiran: 8\n\nRata-rata nilai: 78\nSiswa dengan nilai tertinggi: Citra\nSiswa dengan kehadiran terbaik: Citra\n\nSiswa yang tidak lulus (nilai < 75):\n- Budi (70)\n- Dewi (65)\n\nSiswa dengan kehadiran < 80%:\n- Budi (7 hari hadir)\n- Dewi (6 hari hadir)',1,20,1657,0,1,'2025-05-25 19:36:27','2025-05-25 19:36:28'),(160,145,27,'#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n    const int JUMLAH_SISWA = 5;\n    const int JUMLAH_HARI = 10;\n\n    string nama[JUMLAH_SISWA] = {\"Andi\", \"Budi\", \"Citra\", \"Dewi\", \"Eko\"};\n    int nilai[JUMLAH_SISWA] = {85, 70, 92, 65, 78};\n    int kehadiran[JUMLAH_SISWA] = {9, 7, 10, 6, 8};\n\n    int totalNilai = 0;\n    int indeksTertinggi = 0;\n    int indeksKehadiranTerbaik = 0;\n    float rataRata;\n\n   \n    cout << \"Daftar Siswa:\\n\";\n    for (int i = 0; i < JUMLAH_SISWA; i++) {\n        cout <