a dengan kehadiran terbaik: \" << nama[indeksKehadiranTerbaik] << endl;\n\n    // Identifikasi Siswa yang Tidak Lulus\n    cout << endl << \"Siswa yang tidak lulus (nilai < 75):\" << endl;\n    bool adaTidakLulus = false;\n    for (int i = 0; i < JUMLAH_SISWA; i++) {\n        if (nilai[i] < 75) {\n            cout << \"- \" << nama[i] << \" (\" << nilai[i] << \")\" << endl;\n            adaTidakLulus = true;\n        }\n    }\n    if (!adaTidakLulus) {\n        cout << \"- Tidak ada\" << endl;\n    }\n\n    // Identifikasi Siswa dengan Kehadiran Kurang\n    cout << endl << \"Siswa dengan kehadiran < 80%:\" << endl;\n    bool adaKurangHadir = false;\n    for (int i = 0; i < JUMLAH_SISWA; i++) {\n        float persenHadir = (kehadiran[i] / (float)JUMLAH_HARI) * 100;\n        if (persenHadir < 80) {\n            cout << \"- \" << nama[i] << \" (\" << kehadiran[i] << \" hari hadir)\" << endl;\n            adaKurangHadir = true;\n        }\n    }\n    if (!adaKurangHadir) {\n        cout << \"- Semua siswa hadir cukup\" << endl;\n    }\n\n    return 0;\n}','Daftar Siswa:\nAndi - Nilai: 85, Kehadiran: 9\nBudi - Nilai: 70, Kehadiran: 7\nCitra - Nilai: 92, Kehadiran: 10\nDewi - Nilai: 65, Kehadiran: 6\nEko - Nilai: 78, Kehadiran: 8\n\nRata-rata nilai: 78\nSiswa dengan nilai tertinggi: Citra\nSiswa dengan kehadiran terbaik: Citra\n\nSiswa yang tidak lulus (nilai < 75):\n- Budi (70)\n- Dewi (65)\n\nSiswa dengan kehadiran < 80%:\n- Budi (7 hari hadir)\n- Dewi (6 hari hadir)',1,28,555,0,1,'2025-05-25 19:43:25','2025-05-25 19:43:25'),(171,156,27,'#include <iostream>\n#include <string>\nusing namespace std;\n\nint main() {\n  \n	const int jumlahsiswa=5;\n	const int jumlahhari = 10;\n	\n    string nama[5] = {\"Andi\", \"Budi\", \"Citra\", \"Dewi\", \"Eko\"};\n\n  \n    int nilai[5] = {85, 70, 92, 65, 78};\n\n  \n    int kehadiran[5] = {9, 7, 10, 6, 8};\n\n    int totalNilai = 0;\n	\n    int indeksTertinggi = 0;\n    int indeksKehadiranTerbaik = 0;\n	\n    float rataRata; \n	\n    