"\\nSiswa dengan kehadiran < 80%:\\n\";\n    bool adaKurangHadir = false;\n    for (int i = 0; i < JUMLAH_SISWA; i++) {\n        float persenHadir = (kehadiran[i] / (float)JUMLAH_HARI) * 100;\n        if (persenHadir < 80.0) {\n            cout << \"- \" << nama[i] << \" (\" << kehadiran[i] << \" hari hadir)\" << endl;\n            adaKurangHadir = true;\n        }\n    }\n    if (!adaKurangHadir) {\n        cout << \"- Semua siswa hadir cukup\\n\";\n    }\n\n    return 0;\n}','Daftar Siswa:\nAndi - Nilai: 85, Kehadiran: 9\nBudi - Nilai: 70, Kehadiran: 7\nCitra - Nilai: 92, Kehadiran: 10\nDewi - Nilai: 65, Kehadiran: 6\nEko - Nilai: 78, Kehadiran: 8\n\nRata-rata nilai: 78\nSiswa dengan nilai tertinggi: Citra\nSiswa dengan kehadiran terbaik: Citra\n\nSiswa yang tidak lulus (nilai < 75):\n- Budi (70)\n- Dewi (65)\n\nSiswa dengan kehadiran < 80%:\n- Budi (7 hari hadir)\n- Dewi (6 hari hadir)',1,23,1596,0,1,'2025-05-25 19:50:40','2025-05-25 19:50:40'),(174,159,27,'#include<iostream>\nusing namespace std;\n\nint main(){\n    const int JUMLAH_SISWA = 5;\n    const int JUMLAH_HARI = 10;\n    const int BATAS_LULUS = 75; // Batas kelulusan\n    const int BATAS_KEHADIRAN = 80; // Batas kehadiran minimal (80%)\n    \n    string nama[] = {\"Andi\", \"Budi\", \"Citra\", \"Dewi\", \"Eko\"};\n    int nilai[] = {85, 70, 92, 65, 78};\n    int kehadiran[] = {9, 7, 10, 6, 8};\n    \n    int totalNilai = 0;\n    int indeksNilaiTertinggi = 0;\n    int indeksKehadiranTerbaik = 0;\n    \n    float rataRata;\n    \n    cout << \"Daftar Siswa:\" << endl;\n    \n    // Menampilkan daftar siswa dan menghitung total nilai\n    for(int i = 0; i < JUMLAH_SISWA; i++){\n        cout << nama[i] << \" - Nilai: \" << nilai[i] << \", Kehadiran: \" << kehadiran[i] << endl;\n        totalNilai += nilai[i];\n    }\n    \n    // Mencari siswa dengan nilai tertinggi\n    for(int i = 1; i < JUMLAH_SISWA; i++){\n        if(nilai[i] > nilai[indeksNilaiTertinggi]){\n            indeksNilaiTertinggi = i;\n        }\n    }\n    \n    // Mencari siswa dengan kehadiran terbaik\n    for(int i = 1; i < JUMLAH_SISWA; i++){\n        if(kehadiran[i] > kehadiran[indeksKehadiranTerbaik]){\n            indeksKehadiranTerbaik = i;\n        }\n    }\n    \n    rataRata = (float)totalNilai / JUMLAH_SISWA;\n    \n    cout << endl;\n    cout << \"Rata-rata nilai: \" << rataRata << endl;\n    cout << \"Siswa dengan nilai tertinggi: \" << nama[indeksNilaiTertinggi] \n         << \" (\" << nilai[indeksNilaiTertinggi] << \")\" << endl;\n    cout << \"Siswa dengan kehadiran terbaik: \" << nama[indeksKehadiranTerbaik] \n         << \" (\" << kehadiran[indeksKehadiranTerbaik] << \" hari)\" << endl;\n    \n    cout << endl;\n    \n    // Menampilkan siswa yang tidak lulus (nilai < 75)\n    cout << \"Siswa yang tidak lulus (nilai < \" << BATAS_LULUS << \"):\" << endl;\n    bool adaYangTidakLulus = false;\n    for(int i = 0; i < JUMLAH_SISWA; i++){\n        if(nilai[i] < BATAS_LULUS){\n            cout << \"- \" << nama[i] << \" (\" << nilai[i] << \")\" << endl;\n            adaYangTidakLulus = true;\n        }\n    }\n    if(!adaYangTidakLulus){\n        cout << \"Semua siswa lulus!\" << endl;\n    }\n    \n    cout << endl;\n    \n    // Menampilkan siswa dengan kehadiran < 80%\n    cout << \"Siswa dengan kehadiran < \" << BATAS_KEHADIRAN << \"%:\" << endl;\n    bool adaKehadiranKurang = false;\n    for(int i = 0; i < JUMLAH_SISWA; i++){\n        int persenKehadiran = (kehadiran[i] * 100) / JUMLAH_HARI;\n        if(persenKehadiran < BATAS_KEHADIRAN){\n            cout << \"- \" << nama[i] << \" (\" << kehadiran[i] << \" hari hadir)\" << endl;\n            adaKehadiranKurang = true;\n        }\n    }\n    if(!adaKehadiranKurang){\n        cout << \"Semua siswa memiliki kehadiran baik!\" << endl;\n    }\n    \n    return 0;\n}','Daftar Siswa:\nAndi - Nilai: 85, Kehadiran: 9\nBudi - Nilai: 70, Kehadiran: 7\nCitra - Nilai: 92, Kehadiran: 10\nDewi - Nilai: 65, Kehadiran: 6\nEko - Nilai: 78, Kehadiran