terbaik: \" << nama[indeksKehadiranTerbaik] << endl;\n    \n    // Identifikasi Siswa yang Tidak Lulus\n    cout << endl;\n    cout << \"Siswa yang tidak lulus (nilai < 75):\" << endl;\n    \n    bool adaTidakLulus = false;\n    \n    for (int i = 0; i < JUMLAH_SISWA; i++) {\n        if (nilai[i] < 75) {\n            cout << \"- \" << nama[i] << \" (\" << nilai[i] << \")\" << endl;\n            adaTidakLulus = true;\n        }\n    }\n    \n    if (!adaTidakLulus) {\n        cout << \"- Tidak ada\" << endl;\n    }\n    \n    // Identifikasi Siswa dengan Kehadiran Kurang\n    cout << endl;\n    cout << \"Siswa dengan kehadiran < 80%:\" << endl;\n    \n    bool adaKurangHadir = false;\n    \n    for (int i = 0; i < JUMLAH_SISWA; i++) {\n        float persenHadir = (kehadiran[i] / (float)JUMLAH_HARI) * 100;\n        \n        if (persenHadir < 80) {\n            cout << \"- \" << nama[i] << \" (\" << kehadiran[i] << \" hari hadir)\" << endl;\n            adaKurangHadir = true;\n        }\n    }\n    \n    if (!adaKurangHadir) {\n        cout << \"- Semua siswa hadir cukup\" << endl;\n    }\n    \n    return 0;\n}','Daftar Siswa:\nAndi - Nilai: 85, Kehadiran: 9\nBudi - Nilai: 70, Kehadiran: 7\nCitra - Nilai: 92, Kehadiran: 10\nDewi - Nilai: 65, Kehadiran: 6\nEko - Nilai: 78, Kehadiran: 8\n\nRata-rata nilai: 78.00\nSiswa dengan nilai tertinggi: Citra\nSiswa dengan kehadiran terbaik: Citra\n\nSiswa yang tidak lulus (nilai < 75):\n- Budi (70)\n- Dewi (65)\n\nSiswa dengan kehadiran < 80%:\n- Budi (7 hari hadir)\n- Dewi (6 hari hadir)',0,30,1033,0,1,'2025-06-03 20:46:54','2025-06-03 20:46:54'),(177,162,6,'#include <iostream>\nusing namespace std;\n\nint main() {\n    // Deklarasi dan inisialisasi variabel\n    int panjang = 8;\n    int lebar = 5;\n    double luas = panjang * lebar;\n    string jenis = \"persegi panjang\";\n\n    // Kontrol percabangan\n    if (jenis == \"persegi panjang\") {\n        cout << \"Panjang = \" << panjang << endl;\n        cout << \"Lebar = \" <<